/* DAWAH X — ahmad, অধ্যায় 39 · খণ্ড 39 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][39]=[[7601,7601,"","আমরা আমাদের সব থেকে ভালো খবর নিয়ে কথা বলেছি যে আমার বাবা ঈশ্বরকে বলে যে, তার ভাই যে কাউকে উদ্ধার করবে, ঈশ্বর শেষ পর্যন্ত হবেন। আর মাংসের মধ্যে ঈশ্বরের অস্তিত্ব আছে অতীত ভালোবাসার দেবতাদের... ...তার ভাইয়ের জীবনে কখনোই কোন কাজ হয়নি.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَتَرَ أَخَاهُ الْمُسْلِمَ فِي الدُّنْيَا سَتَرَهُ اللَّهُ فِي الْآخِرَةِ وَمَنْ نَفَّسَ عَنْ أَخِيهِ ‏ ‏كُرْبَةً ‏ ‏مِنْ ‏ ‏كُرَبِ ‏ ‏الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ ‏ ‏كُرْبَةً ‏ ‏يَوْمَ الْقِيَامَةَ وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ ‏","","",""],[7602,7602,"","আমরা আমার বাবাকে ভগবানের কাছে জিজ্ঞেস করতে বলেছিলাম, কে তার নিজের বিজ্ঞানের জন্য দায়ী করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ جَاءَ يَوْمَ الْقِيَامَةَ ‏ ‏مُلْجَمًا ‏ ‏بِلِجَامٍ ‏ ‏مِنْ نَارٍ ‏","","",""],[7603,7603,"","আমরা আমার বাবার প্রতি ঈর্ষা প্রকাশ করেছি, আমার বাবার উপর ভিত্তি করে প্রান্তরে আটকা পড়ে যাওয়ায়। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং সম্প্রদায়ের ক্ষতি করার জন্য প্রার্থনা করেছেন। সাহস আর তার পাপের জন্য লড়াই করা আর তার ইচ্ছা হারার জন্য, সে আমার থেকে নয়.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسِ بْنِ رِيَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ خَرَجَ مِنْ الطَّاعَةِ وَفَارَقَ الْجَمَاعَةَ فَمَاتَ فَمِيتَتُهُ جَاهِلِيَّةٌ وَمَنْ قَاتَلَ تَحْتَ رَايَةٍ ‏ ‏عِمِّيَّةٍ ‏ ‏يَغْضَبُ ‏ ‏لِعَصَبَتِهِ ‏ ‏وَيُقَاتِلُ ‏ ‏لِعَصَبَتِهِ ‏ ‏وَيَنْصُرُ ‏ ‏عَصَبَتَهُ ‏ ‏فَقُتِلَ فَقِتْلَةٌ جَاهِلِيَّةٌ وَمَنْ خَرَجَ عَلَى أُمَّتِي يَضْرِبُ ‏ ‏بَرَّهَا ‏ ‏وَفَاجِرَهَا لَا ‏ ‏يَتَحَاشَى ‏ ‏لِمُؤْمِنِهَا وَلَا يَفِي لِذِي عَهْدِهَا فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ ‏","","",""],[7604,7604,"","আমি বলেছিলাম তোমার খেলা আমার বাবার কাঁধের উপর আছে। আমি তোমাকে বলতে চাই, তোমার যাওয়াটা ভালো হবে। লর্ড তার কাছে প্রার্থনা করে, আর তিনি আমার বাবাকে আত্মসমর্পণ করতে বলেছেন। আমি যে বছরে শপথ করে বলবো, তা হবে ভালো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقُلْتُ لَهُ إِنَّهُ بَلَغَنِي أَنَّكَ تَقُولُ إِنَّ الْحَسَنَةَ تُضَاعَفُ أَلْفَ أَلْفِ حَسَنَةٍ قَالَ وَمَا أَعْجَبَكَ مِنْ ذَلِكَ فَوَاللَّهِ لَقَدْ ‏ ‏سَمِعْتُهُ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَا قَالَ أَبِي ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ لَيُضَاعِفُ الْحَسَنَةَ أَلْفَيْ أَلْفِ حَسَنَةٍ ‏","","",""],[7605,7605,"","আমরা বাবার সাথে কথা বলেছি, প্রভুর শান্তি ত্যাগ করার ব্যাপারে, সে এক বছরের মধ্যে গান গাওয়ার আগে তার মন থেকে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ فُقَرَاءُ الْمُؤْمِنِينَ الْجَنَّةَ قَبْلَ أَغْنِيَائِهِمْ بِخَمْسِ مِائَةِ عَامٍ ‏","","",""],[7606,7606,"","আমরা একজন বাপ্তিস্মের শান্তি নিয়ে কথা বলেছি, বাবার ভালোর প্রমাণ করার জন্য আমার বাবার ভালোর প্রমাণ দিয়ে যে তিনি কখনো ভালবাসা অর্জন করতে পারেননি। তিনি বলেছেন তিনি একজন কুমারী। সিঁড়ি দিয়ে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏زَكَرِيَّا ‏ ‏عَلَيْهِ السَّلَام ‏ ‏نَجَّارًا ‏","","",""],[7607,7607,"","আমার বাবার কাছ থেকে অনেক ভালো বলা হয়েছে। আমার বাবা, আমি যা বলেছি তা হলো একটি ভবিষ্যদ্বাণীর উপহার, যিনি তাকে আদেশ দিয়েছেন এবং আশ্বস্ত করেছেন যে মানুষ হয়তো আমার কাছে পাপ করেছে। তাহলে আমি এটা করেছি। তারপর আমি এটা করেছি। আমি জানি, আমি এটা করেছি। আমি জানি, আমি কি, আমি এটা করেছি? আমি জানি, আমি এটা করেছি, আমি জানি, আমি এটা করেছি, আমি জানি, আমি এটা করেছি, আমি জানি না। আমি এটা আমার বাবা, আমি কি বলেছি। আমি যদি আমার বাবা, আমি এটা করতে চাই। এবং আমি এটা করতে চাই। আমি জানি না যে, আমি জানি না। আমি যদি আমার বাবা, আমি এটা করতে চাই, আমি এটা করতে চাই, আমি কি করবো? হয়তো আমি এটা করেছি। অন্য কোথাও গিয়ে অন্য কোথাও গিয়ে করেছি। আর তারপর আমি যাব, নয়তো অন্য কোথাও যাব। হয়তো তিনি নেকড়েগুলোকে ক্ষমা করে নিয়ে যেতে পারেন এবং আমি হয়তো তাকে নিয়ে যেতে পারি। কিছু একটা প্লে করার জন্য চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا أَذْنَبَ ذَنْبًا فَقَالَ رَبِّ إِنِّي أَذْنَبْتُ ذَنْبًا ‏ ‏أَوْ قَالَ عَمِلْتُ عَمَلًا ذَنْبًا ‏ ‏فَاغْفِرْهُ فَقَالَ عَزَّ وَجَلَّ ‏ ‏عَبْدِي عَمِلَ ذَنْبًا فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِهِ قَدْ غَفَرْتُ لِعَبْدِي ثُمَّ عَمِلَ ذَنْبًا آخَرَ ‏ ‏أَوْ أَذْنَبَ ذَنْبًا آخَرَ ‏ ‏فَقَالَ رَبِّ إِنِّي عَمِلْتُ ذَنْبًا فَاغْفِرْهُ فَقَالَ تَبَارَكَ وَتَعَالَى عَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِهِ قَدْ غَفَرْتُ لِعَبْدِي ثُمَّ عَمِلَ ذَنْبًا آخَرَ ‏ ‏أَوْ أَذْنَبَ ذَنْبًا آخَرَ ‏ ‏فَقَالَ رَبِّ إِنِّي عَمِلْتُ ذَنْبًا فَاغْفِرْهُ فَقَالَ عَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِهِ قَدْ غَفَرْتُ لِعَبْدِي فَلْيَعْمَلْ مَا شَاءَ ‏","","",""],[7608,7608,"","আমরা একটা শপথ নিয়ে কথা বলেছি যে, বাবার হত্যা করার চেষ্টা করেছি... ...আর একটা চিড়িয়াখানা বা ছেলে খুঁজে পেয়েছে. পৃথিবীতেই কাজ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي قَحْذَمٍ ‏ ‏قَالَ ‏ ‏وُجِدَ فِي زَمَنِ ‏ ‏زِيَادٍ ‏ ‏أَوْ ‏ ‏ابْنِ زِيَادٍ ‏ ‏صُرَّةٌ فِيهَا حَبٌّ أَمْثَالُ النَّوَى ‏ ‏عَلَيْهِ مَكْتُوبٌ هَذَا نَبَتَ فِي زَمَانٍ كَانَ يُعْمَلُ فِيهِ بِالْعَدْلِ ‏","","",""],[7609,7609,"","আমরা একটি ছেলে চুরি করার চেষ্টা করেছি, যার বলা হয়েছে, ঈশ্বরের প্রার্থনা যদি ধনীদের হাতে থাকে... ...তাহলে তারা কারা তা জানতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ وَهُوَ الْأَزْرَقُ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُهُ يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ الْعِلْمُ ‏ ‏بِالثُّرَيَّا ‏ ‏لَتَنَاوَلَهُ أُنَاسٌ مِنْ أَبْنَاءِ ‏ ‏فَارِسَ ‏","","",""],[7610,7610,"","আমি আমার বাবাকে একটা উৎপীড়ক বলতে চাই... ...আমি তাকে আগুনে গুলি করব... ...আর আমি আরো বেশি লোক খুঁজে বের করব তোমরা সবাই এর চেয়েও বেশী লোককে.","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اطَّلَعْتُ فِي النَّارِ فَوَجَدْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ وَاطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ ‏","","",""],[7611,7611,"","তিনি বলেছিলেন যে, তিনি যদি পাপ করে থাকেন, তাহলে তিনি পরিতৃপ্তি লাভ করবেন । তারা কী কারণে বৃষ্টি হচ্ছিল, তা তাদের বলুন ।","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ إِذَا أَذْنَبَ كَانَتْ ‏ ‏نُكْتَةٌ ‏ ‏سَوْدَاءُ فِي قَلْبِهِ فَإِنْ تَابَ وَنَزَعَ وَاسْتَغْفَرَ صُقِلَ قَلْبُهُ وَإِنْ زَادَ زَادَتْ حَتَّى يَعْلُوَ قَلْبَهُ ذَاكَ ‏ ‏الرَّيْنُ ‏ ‏الَّذِي ذَكَرَ اللَّهُ عَزَّ وَجَلَّ فِي الْقُرْآنِ ‏ { ‏كَلَّا بَلْ ‏ ‏رَانَ ‏ ‏عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ ‏}","","",""],[7612,7612,"","আমি বাবার সাথে আমার বাবার সমস্যা নিয়ে কথা বলেছিলাম, ঈশ্বর আমার ভাই হাররাকে আদেশ দিয়েছেন আর উনি বলবেন যে এই সাক্ষী কি পাবে।","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يَجِدُ الشَّهِيدُ مِنْ مَسِّ الْقَتْلِ إِلَّا كَمَا يَجِدُ أَحَدُكُمْ مَسِّ ‏ ‏الْقَرْصَةِ ‏","","",""],[7613,7613,"","ঈশ্বর তাকে তিন বার বলেছিলেন, প্রভু তাকে তিন বার এই কথা বলেছিলেন, যিনি তাকে বলেছিলেন যে, ঈশ্বর তাকে বলেছিলেন যে, আমার বাবা একজন পলাতক । ...যে.","‏ ‏حَدَّثَنِي ‏ ‏صَفْوَانُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدِّينُ النَّصِيحَةُ ثَلَاثَ مَرَّاتٍ قَالَ قِيلَ يَا رَسُولَ اللَّهِ لِمَنْ قَالَ لِلَّهِ وَلِكِتَابِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ ‏","","",""],[7614,7614,"","সেই সাক্ষ্যের বিষয়ে বলা হয়েছিল যে, ভাববাদী তার কাছে প্রার্থনা করেছিলেন এবং তিনি পর্যন্ত সাক্ষ্য দিতে রাজি হননি আর তাতে কি আছে?","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي زَيْنَبَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ذُكِرَ الشَّهِيدُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَجِفُّ الْأَرْضُ مِنْ دَمِ الشَّهِيدِ حَتَّى ‏ ‏يَبْتَدِرَهُ ‏ ‏زَوْجَتَاهُ كَأَنَّهُمَا ‏ ‏ظِئْرَانِ ‏ ‏أَظَلَّتَا ‏ ‏أَوْ أَضَلَّتَا ‏ ‏فَصِيلَيْهِمَا ‏ ‏بِبَرَاحٍ ‏ ‏مِنْ الْأَرْضِ بِيَدِ كُلِّ وَاحِدَةٍ مِنْهُمَا ‏ ‏حُلَّةٌ ‏ ‏خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[7615,7615,"","মাহিদির সবচেয়ে ভালোটা নিয়ে আমরা কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ حُسْنَ الظَّنِّ مِنْ حُسْنِ الْعِبَادَةِ ‏","","",""],[7616,7616,"","আমরা আমার বাবার সাথে কথা বলেছি যে শীঘ্রই সে আমার বাবার ব্যাপারে আমাকে বলেছে, সে আমাকে হাত দেবে, আর তারপর ভালো মানুষ যে বলবে আমি তার সাথে আছি, সে বলেছে যে তার আছে। বল কে সে, প্রভু বলল, \"তাড় করে ফেল\"","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قِيلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ النَّاسِ خَيْرٌ قَالَ أَنَا وَمَنْ مَعِي قَالَ فَقِيلَ لَهُ ثُمَّ مَنْ يَا رَسُولَ اللَّهِ قَالَ الَّذِي عَلَى الْأَثَرِ قِيلَ لَهُ ثُمَّ مَنْ يَا رَسُولَ اللَّهِ قَالَ فَرَفَضَهُمْ ‏","","",""],[7617,7617,"","আমার বাবা একজন পলাতক ছিলেন, যিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন যে, মানুষ কখনোই তাঁর সঙ্গে কথা বলবে না । সে আগুনেই থাকবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ لَا يُرِيدُ بِهَا ‏ ‏بَأْسًا ‏ ‏يَهْوِي بِهَا سَبْعِينَ خَرِيفًا فِي النَّارِ ‏","","",""],[7618,7618,"","আমরা সিংহাসনের আগুনকে শান্ত করার চেষ্টা করেছি, আমার বাবার উপর বাজি ধরা হয়েছে, একজন ভালো যোদ্ধা, একজন মহান যোদ্ধা। একজন মহিলাকে ঈশ্বরের সামনে নিজেকে খুঁজে পেতে বলা হয়েছিল, এমনকি তাকে হত্যা করার জন্য বলা হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عَاصِمَ بْنَ عُبَيْدِ اللَّهِ ‏ ‏مِنْ آلِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُبَيْدٍ ‏ ‏مَوْلًى ‏ ‏لِأَبِي رُهْمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏لَقِيَ امْرَأَةً فَوَجَدَ مِنْهَا رِيحَ ‏ ‏إِعْصَارٍ ‏ ‏طَيِّبَةً فَقَالَ لَهَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏الْمَسْجِدَ تُرِيدِينَ قَالَتْ نَعَمْ قَالَ وَلَهُ تَطَيَّبْتِ قَالَتْ نَعَمْ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرَأَةٍ تَطَيَّبَتْ لِلْمَسْجِدِ فَيَقْبَلُ اللَّهُ لَهَا صَلَاةً حَتَّى تَغْتَسِلَ مِنْهُ اغْتِسَالَهَا مِنْ الْجَنَابَةِ فَاذْهَبِي فَاغْتَسِلِي ‏","","",""],[7619,7619,"","আমরা দুই বার একটা ফার্ম বা ভালো জিনিস সম্পর্কে শুনেছি। আমি তার কাছে প্রার্থনা করছি। সে তার আত্মা গোপন করছিল, এটা আমার দোষ আর আমি প্রতিজ্ঞা করছি এটা না যে আমি শান্ত থাকার প্রতিজ্ঞা করছি... ...আমি তাদের কাছে তাদের কাছে তাদের বলতে চাই তারা কি করতে যাচ্ছে কর.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فُرَاتٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏قَالَ ‏ ‏قَاعَدْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏خَمْسَ سِنِينَ ‏ ‏فَسَمِعْتُهُ يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانَتْ ‏ ‏تَسُوسُهُمْ ‏ ‏الْأَنْبِيَاءُ كُلَّمَا هَلَكَ نَبِيٌّ خَلَفَ نَبِيٌّ وَإِنَّهُ لَا نَبِيَّ بَعْدِي إِنَّهُ سَيَكُونُ خُلَفَاءُ فَتَكْثُرُ قَالُوا فَمَا تَأْمُرُنَا قَالَ فُوا بِبَيْعَةِ الْأَوَّلِ فَالْأَوَّلِ وَأَعْطُوهُمْ حَقَّهُمْ الَّذِي جَعَلَ اللَّهُ لَهُمْ فَإِنَّ اللَّهَ سَائِلُهُمْ عَمَّا اسْتَرْعَاهُمْ ‏","","",""],[7620,7620,"","আমরা আবেগ নিয়ে প্রার্থনা করছি, আমরা একটা দাঙ্গার সৃষ্টি করেছি, যা সে তার রাজধানীর জন্য একটা উপহার নিয়ে করেছে। তাকে আমার প্রভু হিসেবে পৌঁছে দিয়েছি... ...আমি কিছু বলতে চাই যদি আমি খুব খারাপ কিছু বলি, তোমার যা কিছু আছে তা হলো, তোমার কাছে আমি নিশ্চিত নই যে আমি তোমার সাথে যাব না। আমার আত্মা থেকে বলছি, তুমি তোমার ফ্ল্যাশ নিয়ে এসেছ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ عَاصِمٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبِرْنِي بِشَيْءٍ أَقُولُهُ إِذَا أَصْبَحْتُ وَإِذَا أَمْسَيْتُ قَالَ ‏ ‏قُلْ اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَشَرِّ الشَّيْطَانِ وَشِرْكِهِ قُلْهُ إِذَا أَصْبَحْتَ وَإِذَا أَمْسَيْتَ وَإِذَا أَخَذْتَ مَضْجَعَكَ ‏","","",""],[7621,7621,"","আমরা বেন ফারাহকে খুঁজে বের করার কথা বলেছিলাম সে বলেছে সে নাকি ভালো মানুষ হতে যাচ্ছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং ওয়াটার্সের লর্ডদের কাছে একটা পৃথিবী পৌঁছে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامٌ إِلَّا الْأَسْوَدَيْنِ التَّمْرَ وَالْمَاءَ ‏","","",""],[7622,7622,"","আমরা ভিড়ের কথা বলেছি, আমরা একটা ফার্নেসের পিছনে যাওয়ার কথা বলেছি। ঈশ্বর তার লোকেরা বলেছে সে ক্লান্ত আর তার ভুলের সময় আমি খুবই বিখ্যাত। আল্লাহ তাকে মাতাল হিসেবে হত্যা করে পার পেয়ে যেতে দেখেছেন, আল্লাহ জানেন, আর যত তাড়াতাড়ি সম্ভব তাদের জীবন যাপন করতে হবে। তারা বলে, লর্ডের ক্ষমতা আছে তাদের অনুপ্রাণিত করতে, তারা এখানে বাস করত এবং তিনি দিনের তৃতীয় তিন মাস পরে ভেঙ্গে যায়.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏هَجَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسَبُهُ قَالَ شَهْرًا ‏ ‏فَأَتَاهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ فِي غُرْفَةٍ عَلَى حَصِيرٍ قَدْ أَثَّرَ الْحَصِيرُ بِظَهْرِهِ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏كِسْرَى ‏ ‏يَشْرَبُونَ فِي الذَّهَبِ وَالْفِضَّةِ وَأَنْتَ هَكَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُمْ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي حَيَاتِهِمْ الدُّنْيَا ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ تِسْعَةٌ وَعِشْرُونَ هَكَذَا وَهَكَذَا وَكَسَرَ فِي الثَّالِثَةِ الْإِبْهَامَ ‏","","",""],[7623,7623,"","আমরা এমন এক আবেগ কথা বলেছি যা ঈশ্বরের অমরত্বের রাতে নিয়ে এসেছে। ঈশ্বর তাকে প্রশ্ন করেছেন এবং আশ্বস্ত করেছেন যে তিনি কবর থেকে উঠে এসেছেন এবং তার গুটিয়ে যাওয়া উচিত ফাঁসির আওয়াজ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَتَعَوَّذُ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ جَهَنَّمَ وَفِتْنَةِ ‏ ‏الدَّجَّالِ ‏","","",""],[7624,7624,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের প্রতিবেশী সময়ের মন ধারণ করতে সাহায্য করেছে। আমি তাদের কয়েকটা জিনিস তৈরি করছি যা আমরা ঈশ্বরের কাছে ভবিষ্যদ্বাণী দিতে যাচ্ছি, তার একটা স্বপ্ন আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ الْجُرَيْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ أَصَابَهُمْ جُوعٌ قَالَ وَنَحْنُ سَبْعَةٌ ‏ ‏فَأَعْطَانِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَ تَمَرَاتٍ لِكُلِّ إِنْسَانٍ تَمْرَةٌ ‏","","",""],[7625,7625,"","আমরা আবেগ আর ভয় নিয়ে কথা বলেছি যে বাবা... ...আমি শুনেছি... ...আমি সাইমনের পাশ দিয়ে যাচ্ছি... ...সে তার মুখ আর তার মুখ নিয়ে কথা বলেছি জিহ্বার মত নয়, আমি তোমাকে শপথ করে বলছি, জোরে জোরে কথা বলো না, আমি হাল ছেড়ে দেবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ أَبِي سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَلَا أُعَلِّمُكَ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏أَفَلَا أَدُلُّكَ ‏ ‏عَلَى كَلِمَةٍ مِنْ كَنْزِ الْجَنَّةِ مِنْ تَحْتِ الْعَرْشِ لَا قُوَّةَ إِلَّا بِاللَّهِ يَقُولُ أَسْلَمَ عَبْدِي وَاسْتَسْلَمَ ‏","","",""],[7626,7626,"","আমরা আবেগ নিয়ে কথা বলেছি যার মানে আবেগ আর ভয় যে ভয় আমরা পেয়েছি ভয় হচ্ছে আমার ভয় সব থেকে বেশী হয়ে যাবে. তারা একটা সাইমন পাশ করেছে. আর বাবাকে আমার প্রভুর কাছে যেতে হতো, সে বলবে আমি কাকে ভালোবাসি আর কে যে বিশ্বাস করে সে ভালোবাসা পায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ أَبِي سُلَيْمٍ ‏ ‏سَمِعْتُ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏و قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَحَبَّ ‏ ‏وَقَالَ ‏ ‏هَاشِمٌ ‏ ‏مَنْ سَرَّهُ ‏ ‏أَنْ يَجِدَ طَعْمَ الْإِيمَانِ فَلْيُحِبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[7627,7627,"","আমরা একটি আবেগ কথা বলেছি যে আমরা একটি ভাল পিতা যে একটি ভাল পিতা কথা শুনতে একটি আবেগ আনা. ঈশ্বর আমাদের উদ্ধার করতে হবে এবং বলে যে আমরা আপনার একজন মানুষকে শাসন করার জন্য তার হাত দ্বারা পরাজিত করছি যা ইচ্ছা করো, ওর পদের পদের কথা বল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَأَذُودَنَّ ‏ ‏رِجَالًا مِنْكُمْ عَنْ حَوْضِي كَمَا ‏ ‏تُذَادُ ‏ ‏الْغَرِيبَةُ مِنْ الْإِبِلِ عَنْ الْحَوْضِ ‏","","",""],[7628,7628,"","আমরা বাবার ঈশ্বরের ইচ্ছার প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি, আমি আপনার কাছে ঐ ভ্রূণ সম্পর্কে জ্ঞান দেব যা আপনার কাছে বলার সবচেয়ে ভাল উপায়। আমি আমার কাছ থেকে গোপন কিছু আনতে চাই। আমি এটা করতে চাই। আমি আমার বাবার ইচ্ছা করি। আমি যদি আমার বাবার ইচ্ছা হয়, আপনি জানেন যে আপনি আপনার কাছে এটা একটা গোপন তথ্য নিয়ে আসবেন। আপনি কি জানেন? আমি আপনাকে যে আপনি জানেন না? আমি আপনাকে যে আপনি জানেন, আপনি জানেন না? আমি আপনাকে যে আপনি জানেন, আপনি জানেন, আপনি আপনার সাথে আছেন। আপনি কি? আপনি জানেন, আপনি জানেন না। আপনি যদি আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন না। আপনি জানেন না। আপনি জানেন না? তোমাদের সবাইকে দেখে রেখো, \"আমার কাছে গিয়ে রাজার কাছে যা, আমি আমার থেকে কাউকে বলবে না\" তিনি বলেছেন সে এটা খারাপভাবে হারিয়ে ফেলেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ عِفْرِيتًا مِنْ الْجِنِّ تَفَلَّتَ عَلَيَّ الْبَارِحَةَ لِيَقْطَعَ عَلَيَّ الصَّلَاةَ فَأَمْكَنَنِي اللَّهُ مِنْهُ ‏ ‏فَدَعَتُّهُ وَأَرَدْتُ أَنْ أَرْبِطَهُ إِلَى جَنْبِ سَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ حَتَّى تُصْبِحُوا فَتَنْظُرُوا إِلَيْهِ كُلُّكُمْ أَجْمَعُونَ قَالَ فَذَكَرْتُ دَعْوَةَ أَخِي ‏ ‏سُلَيْمَانَ ‏ ‏رَبِّ ‏ { ‏هَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي ‏} ‏قَالَ فَرَدَّهُ خَاسِئًا ‏","","",""],[7629,7629,"","আমরা বাবার ঈশ্বরের ইচ্ছার প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি, সে বলত আমি আমার নখে একটা ছেলেকে বাঁচাতে এসেছি যে আমার সাথে কথা বলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنِّي لَأَرْجُو إِنْ طَالَ بِي عُمُرٌ أَنْ أَلْقَى ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِنْ عَجِلَ بِي مَوْتٌ فَمَنْ لَقِيَهُ مِنْكُمْ فَلْيُقْرِئْهُ مِنِّي السَّلَامَ ‏","","",""],[7630,7630,"","আমরা আমার বাবার জন্য ঘোড়ার ব্যাপারে কথা বলেছি, একজন পলাতক যে আমাকে খুন করার চেষ্টা করছে, তোমাকে আমার স্বপ্ন দেখতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَرْجُو إِنْ طَالَتْ بِي حَيَاةٌ أَنْ أُدْرِكَ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِنْ عَجِلَ بِي مَوْتٌ فَمَنْ أَدْرَكَهُ فَلْيُقْرِئْهُ مِنِّي السَّلَامَ ‏","","",""],[7631,7631,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...আমি একটি জাডি আর দয়ালু ছেলের কথা শুনেছি, আমার বাবা একজন রাজকুমারী নাকি আমার কাছে ঈশ্বরের সব থেকে ভালো আছে সে বলেছিল যে, সে তার জীবনের প্রত্যক্ষদর্শী।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏وَيُونُسَ بْنَ عُبَيْدٍ ‏ ‏يُحَدِّثَانَ عَنْ ‏ ‏عَمَّارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَمَّا ‏ ‏عَلِيٌّ ‏ ‏فَرَفَعَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَّا ‏ ‏يُونُسُ ‏ ‏فَلَمْ يَعْدُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ فِي هَذِهِ الْآيَةِ ‏ { ‏وَشَاهِدٍ وَمَشْهُودٍ ‏} ‏قَالَ ‏ ‏يَعْنِي الشَّاهِدَ يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏وَالْمَوْعُودَ يَوْمَ الْقِيَامَةَ ‏","","",""],[7632,7632,"","এই বিশ্বাস নিয়ে সাক্ষ্য দেওয়া এবং সাক্ষ্য দেওয়া হল সাক্ষ্য, যার মধ্যে মাটির প্রান্ত ও এর মধ্যে রেখার অবস্থান । ক্র্যাডেলের নিচে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمَّارًا ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّهُ ‏ ‏قَالَ فِي هَذِهِ الْآيَةِ ‏ { ‏وَشَاهِدٍ وَمَشْهُودٍ ‏} ‏قَالَ ‏ ‏الشَّاهِدُ يَوْمَ الْجُمُعَةِ وَالْمَشْهُودُ يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏وَالْمَوْعُودُ يَوْمَ الْقِيَامَةِ ‏","","",""],[7633,7633,"","আমরা আমাদের কামনায় বাপ্তাইজিত হয়েছি... ...যে ছায়ার ছায়া আমাদের কাছে নিয়ে এসেছে... ...যে ছায়ার জন্য প্রার্থনা করেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং বাবাকে শপথ করার জন্য। আমার মায়ের বলা হয়েছে, আমি হাঙ্গর থেকে একটা বোকা ছেলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ ظَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏الصَّادِقَ الْمَصْدُوقَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَلَاكَ أُمَّتِي ‏ ‏أَوْ فَسَادَ أُمَّتِي ‏ ‏رُءُوسٌ أُمَرَاءُ ‏ ‏أُغَيْلِمَةٌ ‏ ‏سُفَهَاءُ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏","","",""],[7634,7634,"","আমরা আবেগ নিয়ে কথা বলেছি যার মানে বন্য মানুষের সাথে ব্যবহৃত আবেগের ছেলে, ঈশ্বর আদেশ দিয়েছেন আর তিনি আত্মসমর্পণ করবেন যে তিনি পড়ে গেছেন তিন বার চাঁদ তিনি পর্বতের মধ্যে জয় করেছেন, মালিক!","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ الْجُشَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ سُورَةً مِنْ الْقُرْآنِ ثَلَاثُونَ آيَةً شَفَعَتْ لِرَجُلٍ حَتَّى غُفِرَ لَهُ وَهِيَ ‏ ‏تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ ‏","","",""],[7635,7635,"","আমরা ঈর্ষার কথা বলেছি, যখন আমার বাবা কথা বলছিল, আমি ঈশ্বরের প্রতি ভালোবাসা শুনেছি। আমার বাবা আমার বাবার প্রতি দয়া দেখান, কিন্তু তিনি এটা গান গেয়েছেন। ঈশ্বর তা করবেন এবং তিনি ফিরে আসবেন। শার্ক এবং কসি থেকে এই ছবি নেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدَ اللَّهِ بْنَ أَبِي نُعْمٍ ‏ ‏يُحَدِّثُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏إِنَّمَا هُوَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي نُعْمٍ ‏ ‏وَلَكِنْ ‏ ‏غُنْدَرٌ ‏ ‏كَذَا ‏ ‏قَالَ إِنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏كَسْبِ الْحَجَّامِ ‏ ‏وَكَسْبِ ‏ ‏الْبَغِيِّ ‏ ‏وَثَمَنِ الْكَلْبِ قَالَ ‏ ‏وَعَسْبِ ‏ ‏الْفَحْلِ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏هَذِهِ مِنْ كِيسِي ‏","","",""],[7636,7636,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমার ভালবাসার অনুভূতি পরিবর্তন করতে চেষ্টা করেছি, আমার ভালোবাসা মুক্ত। আমার বাবা একটা উপহার, তিনি বলেছিলেন আমি আমার বাবার চিতাবাঘের সাথে ছিলাম, তার প্রভুর লর্ড, তার ঈশ্বর। আমরা এটাকে পাগলামীর জন্য না বলতে চাচ্ছি, কিন্তু ঈশ্বরের অনুগ্রহের জন্য, তার ইচ্ছার কথা অনুযায়ী, আমি তা করতে পারি বা না হয় আমি তাকে খুশি করব। ( গীতসংহিতা ৩৭: ১১) তাই, আমাদের অবশ্যই ঈশ্বরের ওপর নির্ভর করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مُحَرَّرِ بْنِ أَبِي هُرَيْرَةَ ‏ ‏عَنْ أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏حِينَ ‏ ‏بَعَثَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏بِبَرَاءَةٌ ‏ ‏فَقَالَ مَا كُنْتُمْ تُنَادُونَ قَالَ كُنَّا ‏ ‏نُنَادِي أَنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا مُؤْمِنٌ وَلَا يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏عُرْيَانٌ وَمَنْ كَانَ بَيْنَهُ وَبَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهْدٌ فَإِنَّ أَجَلَهُ أَوْ أَمَدَهُ إِلَى أَرْبَعَةِ أَشْهُرٍ فَإِذَا مَضَتْ الْأَرْبَعَةُ الْأَشْهُرِ فَإِنَّ اللَّهَ بَرِيءٌ مِنْ الْمُشْرِكِينَ وَرَسُولُهُ وَلَا يَحُجُّ هَذَا ‏ ‏الْبَيْتَ ‏ ‏بَعْدَ الْعَامِ مُشْرِكٌ قَالَ فَكُنْتُ ‏ ‏أُنَادِي حَتَّى ‏ ‏صَحِلَ ‏ ‏صَوْتِي ‏","","",""],[7637,7637,"","আমরা আমার বাবার জন্য ঘোড়ার কথা বলেছি, একজন পলাতক যে আমাকে খুন করতে চাইছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَرْجُو إِنْ طَالَتْ بِي حَيَاةٌ أَنْ أُدْرِكَ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏فَإِنْ عَجِلَ بِي مَوْتٌ فَمَنْ أَدْرَكَهُ مِنْكُمْ فَلْيُقْرِئْهُ مِنِّي السَّلَامَ ‏","","",""],[7638,7638,"","আমরা বাবার ভুল করার জন্য দু বছর কথা বলেছি। আমি বলতে চাচ্ছি, ভাববাদীরা তার কাছে প্রার্থনা করছে এবং আমি তার দিকে তাকিয়ে আছি,","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَطَبَ رَجُلٌ امْرَأَةً ‏ ‏يَعْنِي مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْظُرْ إِلَيْهَا فَإِنَّ فِي أَعْيُنِ ‏ ‏الْأَنْصَارِ ‏ ‏شَيْئًا ‏","","",""],[7639,7639,"","আমরা দুই বছর ধরে আমার বাবার কথা বলেছি আমার বাবা একজন পলাতক হিসেবে আমার বাবার সম্পর্কে কথা বলেছে। লর্ড তার জন্য প্রার্থনা করেছে এবং তুমি তাকে আত্মসমর্পণ করবে এবং বলবে যে, তুমি আঘাত করবে এবং বলবে যে, তারা একবারই মানুষকে আঘাত করবে। আমি পৃথিবীর এমন কিছু জানি না যা আমি লর্ডের কাছে ঋণী... ...আর বলে যে এটা আমেরিকানদের কাজ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ تَضْرِبُوا ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أَنْ يَضْرِبَ النَّاسُ ‏ ‏أَكْبَادَ الْإِبِلِ يَطْلُبُونَ الْعِلْمَ لَا يَجِدُونَ عَالِمًا أَعْلَمَ مِنْ عَالِمِ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏وَقَالَ قَوْمٌ هُوَ ‏ ‏الْعُمَرِيُّ ‏ ‏قَالَ فَقَدَّمُوا ‏ ‏مَالِكًا ‏","","",""],[7640,7640,"","আমরা আমার বাবার ছেলের ব্যাপারে দুজন ছেলের কথা বলেছি, যে আমার বাবার ব্যাপারে কথা বলতে চায়, ঈশ্বরের কাছে তার চাকরকে আত্মসমর্পণ করতে হবে, তাই আমি তার দাসকে তার খাবার আর তার মুক্তির কথা দিচ্ছি পরাজিত হয়েছে, তারপর তাকে এটা দিয়ে দাও।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي صَالِحٍ يَعْنِي سُهَيْلًا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يُخْبِرُهُمْ ‏ ‏ذَلِكَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَفَى أَحَدَكُمْ خَادِمُهُ صَنْعَةَ طَعَامِهِ وَكَفَاهُ حَرَّهُ وَدُخَانَهُ فَلْيُجْلِسْهُ مَعَهُ فَلْيَأْكُلْ فَإِنْ أَبَى فَلْيَأْخُذْ لُقْمَةً فَلْيُرَوِّغْهَا ثُمَّ لِيُعْطِهَا إِيَّاهُ ‏","","",""],[7641,7641,"","সে আমার বাবার মাখনের মাখনটা পড়ে আমার মায়ের কাছে অনেক অভিজ্ঞ একটা কুত্তার বাচ্চা, সে একটা উজ্জ্বল বাচ্চা, সে নাকি আমার বাবা-মা'র উপহার। তাকে বলা হয়েছে যে সে সুখী, তারা তাদের বলে আমরা ধন্যবাদ দিচ্ছি আর তোমার থেকে ভালো অনুভব করব।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏أَبِي قُرَّةَ الزُّبَيْدِيِّ مُوسَى بْنِ طَارِقٍ ‏ ‏عَنْ ‏ ‏مُوسَى يَعْنِي ابْنَ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏وَعَطَاءِ بْنِ يَسَارٍ ‏ ‏أَوْ عَنْ أَحَدِهِمَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتُحِبُّونَ أَنْ تَجْتَهِدُوا فِي الدُّعَاءِ قُولُوا اللَّهُمَّ أَعِنَّا عَلَى شُكْرِكَ وَذِكْرِكَ وَحُسْنِ عِبَادَتِكَ ‏","","",""],[7642,7642,"","আমরা একজন অতিথির কথা বলেছিলাম যে আমার বাবার ছেলে বা মৃত্যুর ভয়ে... ...তার কথা বলেছিল. রেশমের শিখা।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقْطَعُ الصَّلَاةَ الْمَرْأَةُ وَالْكَلْبُ وَالْحِمَارُ ‏","","",""],[7643,7643,"","বাবার সবচেয়ে ভালো ভালবাসার কথা বলেছিলাম, ঈশ্বর বলে দিয়েছেন যে সে হাল ছেড়ে দেবে যদি আমি জানতে পারি সে আমার সাথে সংযোগ দেখতে পাবে। সে ভুল করেছে। আমার ভাড়ার সাথে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ أَحَدَكُمْ يَعْلَمُ أَنَّهُ إِذَا شَهِدَ الصَّلَاةَ مَعِي كَانَ لَهُ أَعْظَمُ مِنْ شَاةٍ سَمِينَةٍ أَوْ شَاتَيْنِ لَفَعَلَ فَمَا يُصِيبُ مِنْ الْأَجْرِ أَفْضَلُ ‏","","",""],[7644,7644,"","আমরা আমাদের সাম্প্রতিক ছেলেদের সাথে কথা বলেছি যারা আমার বাবাকে বিয়ে করার জন্য দৃঢ়সংকল্পবদ্ধ ছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏خَطَبَ رَجُلٌ امْرَأَةً ‏ ‏يَعْنِي مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏انْظُرْ إِلَيْهَا ‏ ‏يَعْنِي أَنَّ فِي أَعْيُنِ ‏ ‏الْأَنْصَارِ ‏ ‏شَيْئًا ‏","","",""],[7645,7645,"","আমরা শুধু দুই বার ভুলে গেছি যে, ঈশ্বরের চেয়ে আমার ভালোবাসার চেয়ে ভালো আছে। ঈশ্বরের কাছে প্রার্থনা করা তার কাছে একটা আনন্দের বিষয় হবে এবং সে হয়ত এমন একজন ব্যক্তিকে দিয়ে যাবে যে কিনা কিনা কিনা চেষ্টা করেছে। তাকে মারতে আমরা তার হাতে মারছি আর আমরা তাকে মারলাম আর সে কিছু ক্ষমতা জিতে গেল। ঈশ্বর প্রার্থনা করছেন যেন সে এখানে না বলে যে তোমাকে তাকে দিয়ে দিতে হবে না। শয়তান কিন্তু আল্লাহ বলে","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِرَجُلٍ قَدْ شَرِبَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اضْرِبُوهُ قَالَ فَمِنَّا الضَّارِبُ بِيَدِهِ وَمِنَّا الضَّارِبُ بِنَعْلِهِ وَالضَّارِبُ بِثَوْبِهِ فَلَمَّا انْصَرَفَ قَالَ بَعْضُ الْقَوْمِ أَخْزَاكَ اللَّهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُولُوا هَكَذَا لَا تُعِينُوا عَلَيْهِ الشَّيْطَانَ وَلَكِنْ قُولُوا رَحِمَكَ اللَّهُ ‏","","",""],[7646,7646,"","দুই বছর আগে আমরা বাবার সম্ভাব্যত্ব শুনতে করেছি যে তিনি একটি গরু তাকে সরিয়ে ফেলা হয়েছে, এবং আমরা ছিল প্রায় দুই মাস এবং আমরা ছিলাম ভাল ছিল তার কাছে দুটো তরবারি আছে, একবার বলেছিলেন যে তার পিতা বাবা... ...হেরা, তোমার জন্য, ঈশ্বরের ইচ্ছার কথা বলে তাকে ছেড়ে দিয়েছে। তিন বছর আগে আমাকে কথা বলার চেষ্টা করতে হয়নি, যাতে সে আমার কথা শুনতে পারে। সে সব কিছু দেখিয়েছে, যাতে সে একটা গান গাইতে পারে। আমি গান গাইলাম, হাত দিয়ে তাদের অন্ধকার দ্বারা হত্যা করা হবে.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ ‏ ‏نَزَلَ عَلَيْنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏بِالْكُوفَةِ ‏ ‏قَالَ فَكَانَ بَيْنَهُ وَبَيْنَ مَوْلَانَا قَرَابَةٌ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَهُوَ مَوْلَى ‏ ‏الْأَحْمَسِ ‏ ‏فَاجْتَمَعَتْ ‏ ‏أَحْمَسُ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏فَأَتَيْنَاهُ نُسَلِّمُ عَلَيْهِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً فَأَتَاهُ الْحَيُّ ‏ ‏فَقَالَ لَهُ أَبِي يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَؤُلَاءِ أَنْسِبَاؤُكَ أَتَوْكَ يُسَلِّمُونَ عَلَيْكَ وَتُحَدِّثُهُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَرْحَبًا بِهِمْ وَأَهْلًا صَحِبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ سِنِينَ لَمْ أَكُنْ أَحْرَصَ عَلَى أَنْ أَعِيَ الْحَدِيثَ مِنِّي فِيهِنَّ حَتَّى سَمِعْتُهُ يَقُولُ وَاللَّهِ ‏ ‏لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلًا فَيَحْتَطِبَ عَلَى ظَهْرِهِ فَيَأْكُلَ وَيَتَصَدَّقَ خَيْرٌ لَهُ مِنْ أَنْ يَأْتِيَ رَجُلًا أَغْنَاهُ اللَّهُ عَزَّ وَجَلَّ مِنْ فَضْلِهِ فَيَسْأَلَهُ أَعْطَاهُ أَوْ مَنَعَهُ ثُمَّ قَالَ هَكَذَا بِيَدِهِ قَرِيبٌ مِنْ بَيْنِ يَدَيْ السَّاعَةِ سَتَأْتُونَ تُقَاتِلُونَ قَوْمًا نِعَالُهُمْ الشَّعَرُ كَأَنَّ وُجُوهَهُمْ ‏ ‏الْمَجَانُّ ‏ ‏الْمُطْرَقَةُ ‏","","",""],[7647,7647,"","আমরা ভাল হওয়ার ব্যাপারে কথা বলেছি আর এটা ভালো হওয়ার চেয়ে ভালো। আমার বাবা ভবিষ্যদ্বাণীর উপহার, যিনি তাকে আদেশ দিয়েছেন আর বলবে আমি আমার পর্দা মেনে নিচ্ছি। সে জানে বা বল সে বলে। সে এটা চালাচ্ছে আর আমি এটা দৌড়াচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ وَهُوَ الْوَاسِطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ ‏ ‏اسْتَقْرَضْتُ ‏ ‏عَبْدِي فَلَمْ ‏ ‏يُقْرِضْنِي ‏ ‏وَيَشْتُمُنِي عَبْدِي وَهُوَ لَا يَدْرِي يَقُولُ وَا ‏ ‏دَهْرَاهْ وَا ‏ ‏دَهْرَاهْ وَأَنَا الدَّهْرُ ‏","","",""],[7648,7648,"","আমরা বেশ কয়েকবার কথা বলেছি যে আমার বাবা আমার বাবাকে শিখার জন্য রাজি, তাকে আগুন শেখাও না, ঈশ্বর আদেশ দিয়েছেন আর বানরগুলোকে আত্মসমর্পণ করতে হবে গত কয়েক মাসে তুমি যা করেছো, তার জন্য তুমি তাকে তার দুনিয়ায় হারানোর জন্য দায়ী করেছ।","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَزَلَ الْقُرْآنُ عَلَى سَبْعَةِ أَحْرُفٍ ‏ ‏الْمِرَاءُ ‏ ‏فِي الْقُرْآنِ كُفْرٌ ثَلَاثَ مَرَّاتٍ فَمَا عَرَفْتُمْ مِنْهُ فَاعْمَلُوا وَمَا جَهِلْتُمْ مِنْهُ فَرُدُّوهُ إِلَى عَالِمِهِ ‏","","",""],[7649,7649,"","আমরা আমার বাবা তার কাছে একজন পলাতক হিসেবে কথা বলেছি, সে স্যাম বা অন্য একদিনের জন্য তার নাম ছেড়ে দেবে, আর তাকে দুই বছরের জন্য গুলি করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ زَحْزَحَ اللَّهُ وَجْهَهُ عَنْ النَّارِ بِذَلِكَ سَبْعِينَ خَرِيفًا ‏","","",""],[7650,7650,"","আমরা বাবার ছেলেকে কথা বলেছি যখন আমরা তার সাথে কথা বলেছি। আমার বাবা একজন পলাতক। আমার বাবা বলেছেন, আমি প্রার্থনা করছি এবং একজন আল্লাহ তাকে শান্তি কামনা করেছেন। আর ছায়ার পাশে সে আত্মসমর্পণ করে, আর পাখিরা ভয় পায় আর তারা গ্রীষ্মের ছোট ছোট ছোট বিন্দু দিয়ে চলে যায় আর সূর্য খুবই দরিদ্র । নির্বোধ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا صَلَّيْتُ وَرَاءَ أَحَدٍ بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْبَهَ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فُلَانٍ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏كَانَ يُطِيلُ الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الظُّهْرِ وَيُخَفِّفُ الْأُخْرَيَيْنِ وَيُخَفِّفُ الْعَصْرَ وَيَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ ‏ ‏الْمُفَصَّلِ ‏ ‏وَيَقْرَأُ فِي الْعِشَاءِ بِوَسَطِ ‏ ‏الْمُفَصَّلِ ‏ ‏وَيَقْرَأُ فِي الصُّبْحِ بِطِوَالِ ‏ ‏الْمُفَصَّلِ ‏","","",""],[7651,7651,"","আমরা প্রবল আবেগে বাপ্তাইজিত হয়েছি, ঈশ্বরের প্রভুর প্রার্থনা শোনার জন্য, আমি এমন একজন মানুষ যে বলে, আমি প্রথম সুযোগ পেয়েছি তাদের কাছে পৌঁছাতে এবং হতে। আমি আপনাদের কাছে যেতে চাই, আমি এখন আমার প্রথম সুযোগ আছে তাদের কাছে এবং আমি আছি ঈশ্বরের কাছে। আমি কি বলছি, আমি কি করতে পারি? আমি কি করতে পারি? আমি জানি না, আমি কি করতে পারি? আমি জানি না, আমি যদি না, আমি এটা আমার কাছে এটা একটা জিনিস আছে। আমি কি করছি? আমি কি করছি? আমি জানি না? আমি যদি আমার কাছে এটা একটা ছোট মেয়ে না, আমি এটা একটা জিনিস আছে? আমি কি করছি? আমি কি করছি? আমি জানি না? আমি কি করবো? আমি জানি না? আমি কি করবো? আমি এটা আমার কাছে এটা একটা বিষয় নিয়ে কথা বলতে পারি? আমি যদি তুমি জানো না, আমি এটা আমার বাবা-মাজিকতালি না। আমি এটা আমার বাবা-মাদারি, আমি কি করবো? তিনি বললেন, তুমি যখন এটা করলে, তখন তুমি তোমার সাথে খারাপ ব্যবহার করতে গেলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي قَرَابَةً أَصِلُهُمْ وَيَقْطَعُونَ وَأُحْسِنُ إِلَيْهِمْ وَيُسِيئُونَ إِلَيَّ وَأَحْلُمُ عَنْهُمْ وَيَجْهَلُونَ عَلَيَّ قَالَ لَئِنْ كُنْتَ كَمَا تَقُولُ فَكَأَنَّمَا تُسِفُّهُمْ ‏ ‏الْمَلَّ ‏ ‏وَلَا يَزَالُ مَعَكَ مِنْ اللَّهِ ظَهِيرٌ عَلَيْهِمْ مَا دُمْتَ عَلَى ذَلِكَ ‏","","",""],[7652,7652,"","আমরা প্রবল আবেগে বাপ্তাইজিত হয়েছি, আমরা প্রভুর সাথে কথা বলেছি, লর্ডের কাছে প্রার্থনা করেছে এবং আশ্বস্ত হয়েছি যে, সে হবে সেই হবে। আমি নিশ্চিত আমরা আমাদের ভাই-ভাইকে দেখেছি, যদি আমি চেষ্টা করি তাহলে তাদের সাথে বিশ্বাসঘাতকতা করবে, তারপর আমরা তোমার চলে যাবো। মা বলেছিল যে যদি কোন মানুষ পছন্দ করত, তাহলে তার চমৎকার ওক থাকত। তিনি বলেছিলেন, আলো তাদের উপর প্রভাব ফেলার পর তারা খুব শীঘ্রই মারা যাবে। তোমরা আমাকে বলছে কিভাবে? সে তাদের জন্য সবচেয়ে অন্ধকার হবে... ...আমি তাদের ফোন করছি সে চলে গেছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَتَى إِلَى الْمَقْبَرَةِ فَسَلَّمَ عَلَى أَهْلِ الْمَقْبَرَةِ فَقَالَ ‏ ‏سَلَامٌ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ ثُمَّ قَالَ وَدِدْتُ أَنَّا قَدْ رَأَيْنَا إِخْوَانَنَا قَالَ فَقَالُوا يَا رَسُولَ اللَّهِ أَلَسْنَا بِإِخْوَانِكَ قَالَ بَلْ أَنْتُمْ أَصْحَابِي وَإِخْوَانِي الَّذِينَ لَمْ يَأْتُوا بَعْدُ وَأَنَا ‏ ‏فَرَطُهُمْ ‏ ‏عَلَى الْحَوْضِ فَقَالُوا يَا رَسُولَ اللَّهِ كَيْفَ تَعْرِفُ مَنْ لَمْ يَأْتِ مِنْ أُمَّتِكَ بَعْدُ قَالَ أَرَأَيْتَ لَوْ أَنَّ رَجُلًا كَانَ لَهُ خَيْلٌ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلَةٌ ‏ ‏بَيْنَ ظَهْرَانَيْ خَيْلٍ بُهْمٍ ‏ ‏دُهْمٍ ‏ ‏أَلَمْ يَكُنْ يَعْرِفُهَا قَالُوا بَلَى قَالَ فَإِنَّهُمْ يَأْتُونَ يَوْمَ الْقِيَامَةِ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ أَثَرِ الْوُضُوءِ وَأَنَا ‏ ‏فَرَطُهُمْ ‏ ‏عَلَى الْحَوْضِ ثُمَّ قَالَ أَلَا ‏ ‏لَيُذَادَنَّ ‏ ‏رِجَالٌ مِنْكُمْ عَنْ حَوْضِي كَمَا ‏ ‏يُذَادُ ‏ ‏الْبَعِيرُ الضَّالُّ ‏ ‏أُنَادِيهِمْ أَلَا هَلُمَّ فَيُقَالُ إِنَّهُمْ بَدَّلُوا بَعْدَكَ فَأَقُولُ ‏ ‏سُحْقًا ‏ ‏سُحْقًا ‏","","",""],[7653,7653,"","আমরা আমাদের আবেগ-ভাবনা নিয়ে কথা বলেছি... ...যে শুনানির রীতি নিয়ে আমি এসেছি... ...ঈশ্বর আমার ভালবাসার জন্য কথা বলেছেন, ঈশ্বর তাকে দুইবার বা তিনবার ছেড়ে দিতে বলেছেন পরিবর্তন হয়েছে এবং কখনো হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ الْمُؤْمِنُ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا يَغَارُ ‏ ‏يَغَارُ وَاللَّهُ أَشَدُّ غَيْرًا ‏","","",""],[7654,7654,"","আমরা কামনা নিয়ে কথা বলেছি যখন আমরা আমার বাবার মুক্তির খবর শুনতে একটা দাঙ্গার কথা বলছি, ঈশ্বর আপনাকে ভাবতে দিয়েছেন কি হচ্ছে। প্রার্থনা করার এবং এর শক্তির উপর আলো তৈরি করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى مَا يَرْفَعُ اللَّهُ بِهِ الدَّرَجَاتِ ‏ ‏وَيَمْحُو بِهِ الْخَطَايَا كَثْرَةُ الْخُطَى إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ ‏ ‏وَإِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى ‏ ‏الْمَكَارِهِ ‏","","",""],[7655,7655,"","আমরা কামনার কথা বলেছি যখন আমরা দাঙ্গার কথা বলি আমার বাবার মুক্তির কথা শুনে। ঈশ্বর তার সত্য তুলে ধরেন। যদি সে বেঁচেও থাকে, তাহলে তাকে নিয়ে যাও।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَتُؤَدُّنَّ الْحُقُوقَ إِلَى أَهْلِهَا يَوْمَ الْقِيَامَةِ حَتَّى يُقَادَ لِلشَّاةِ ‏ ‏الْجَلْحَاءِ ‏ ‏مِنْ ‏ ‏الْقَرْنَاءِ ‏ ‏تَنْطَحُهَا ‏","","",""],[7656,7656,"","আমরা ঈশ্বরের প্রতি দয়া দেখানোর জন্য মহান এক ছেলের প্রতি করুণা প্রদর্শন করলাম, আমি এক নির্দিষ্ট এলাকায় ছিলাম, যেখানে আমার সাথে কারো সাথে কথা বলা নয়, সে কথা বলতে নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عَبْدِ اللَّهِ الْقُمِّيِّ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ حُمَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زِيَادُ بْنُ حُدَيْرٍ ‏ ‏وَدِدْتُ أَنِّي فِي ‏ ‏حَيِّزٍ ‏ ‏مِنْ حَدِيدٍ مَعِي مَا يُصْلِحُنِي لَا أُكَلِّمُ النَّاسَ وَلَا يُكَلِّمُونِي ‏","","",""],[7657,7657,"","আমরা কামনার কথা বলেছি যখন আমরা দাঙ্গার কথা বলি, আমার বাবার মুক্তির কথা শুনে আমার বাবার সাথে কথা শোনা যায়। ঈশ্বরের ইচ্ছা আছে যে তিনি তার শেষ করেছেন। হুইলারপুল আর বলেছে সে ভাগ্য থেকে ফিরে আসবে না... ...অথবা প্রভুর কাছে ব্যবহার করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ النَّذْرِ وَقَالَ لَا يَرُدُّ مِنْ الْقَدَرِ وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[7658,7658,"","আমরা কামনা নিয়ে কথা বলেছি যখন আমরা একটি দাঙ্গার কথা শুনেছি যেটা আমার ভাই মুক্ত হওয়ার ব্যাপারে আমার বাবার কথা শুনেছি, ঈশ্বর বলে আমরা ভালো কিছু করতে পারি, আর এটা হচ্ছে তার কাজ। আর এটা হচ্ছে আমাদের জন্য। আমি যা করেছি তা হল, আমরা যা করেছি তা হল, আমরা যা করেছি তা হল, আমরা ভাল কাজ করছি। আমি কি করছি তা হল, আমরা যদি না জানি? আমি জানি না? আমি জানি, আমি জানি না যে, আমি এটা আমার বাবা, আমি কি করেছি? এবং আমি জানি না? আমি জানি না, আমি জানি না। আমি জানি না, আমি জানি না, আমি এটা আমার বাবা, আমি কি করে না। আমি জানি না। আমি জানি না। আমি এটা করতে পারি না। আমি কি করবো? আমি জানি না। আমি জানি না, আমি যদি আমি এটা আমার বাবা আমাকে এটা করতে হবে। আমি কি করে না। আমি এটা করতে পারি। আমি জানি না। আমি যখন আমি এটা করতে পারি, আমি যখন আমি এটা করতে পারি, আমি এটা আমার বাবা, আমি জানি যে, আমি জানি যে, আমি জানি যে, আমি জানি না। আমি এটা আমার বাবা-মাখড়িকে পছন্দ করি। আর আমি যখন আমি যখন আমি এটা করতে পারি। এবং আমি যখন আমি এটা করতে পারি, আমি যখন আমি যখন আমি এটা আমার বাবা, আমি এটা ধন্যবাদ দেওয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ ‏ ‏أَنَا خَيْرُ الشُّرَكَاءِ فَمَنْ عَمِلَ عَمَلًا فَأَشْرَكَ فِيهِ غَيْرِي فَأَنَا بَرِيءٌ مِنْهُ وَهُوَ لِلَّذِي أَشْرَكَ ‏","","",""],[7659,7659,"","আমরা বাবার মৃত্যুর ব্যাপারে কথা বলতে বলেছিলাম, সে আমাকে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল আর সে ঈশ্বরের দোহাইর কাছে প্রার্থনা করতো... ঈর্ষা, আমরা তার থেকে নির্দোষ এবং সে আপনার পানীয় জন্য।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا خَيْرُ الشُّرَكَاءِ مَنْ عَمِلَ لِي عَمَلًا فَأَشْرَكَ فِيهِ غَيْرِي فَأَنَا مِنْهُ بَرِيءٌ وَهُوَ لِلَّذِي أَشْرَكَ ‏","","",""],[7660,7660,"","আমরা আমার ছেলের আবেগ নিয়ে কথা বলেছি, আমরা সমস্যা নিয়ে এসেছি, আমরা বলতে চাই শিকারী তার ইচ্ছা তুলে না বললেই সবচেয়ে ভালো হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏الصَّادِقَ الْمَصْدُوقَ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَاحِبَ الْحُجْرَةِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏كَتَبَ بِهِ إِلَيَّ وَقَرَأْتُهُ عَلَيْهِ ‏ ‏يَعْنِي ‏ ‏مَنْصُورًا ‏","","",""],[7661,7661,"","আমরা এক নিষ্ঠুর বাবা যে কাপুরুষ, তার ব্যাপারে আমরা তীব্র আবেগ নিয়ে প্রার্থনা করেছি, যুদ্ধ আর যুদ্ধ অন্ধকার হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ وَالْعَجْوَةُ مِنْ الْجَنَّةِ وَمَاؤُهَا شِفَاءٌ مِنْ السُّمِّ ‏","","",""],[7662,7662,"","আমরা বাবার ভ্রমণকারীর কথা বলছিলাম আমাকে বন্য বাবা বলা হয়েছে, ঈশ্বর তাকে বলেছেন কেন তিনি আপনার বন্দী হবেন না, তিনি বলেছেন তিনি হয়ত বলেছেন। তোমাকে এমন একজনের সাথে নিয়ে যাওয়া হয়েছিল যে ডাইনি ছিল... ...যেটা আমরা একটা প্রতিবাদ করেছিলাম। আচ্ছা, আমি আমার বাবার ভালো মেয়ে শুনেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي زِيَادٍ الطَّحَّانِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ رَأَى رَجُلًا يَشْرَبُ قَائِمًا فَقَالَ لَهُ ‏ ‏قِه ‏ ‏قَالَ ‏ ‏لِمَهْ ‏ ‏قَالَ ‏ ‏أَيَسُرُّكَ أَنْ يَشْرَبَ مَعَكَ ‏ ‏الْهِرُّ ‏ ‏قَالَ لَا قَالَ فَإِنَّهُ قَدْ شَرِبَ مَعَكَ مَنْ هُوَ شَرٌّ مِنْهُ الشَّيْطَانُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي زِيَادٍ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَذَكَرَهُ ‏","","",""],[7663,7663,"","আমাদের দু'জন চেষ্টা দ্বারা আমরা আঘাত পেয়েছি আমার বাবার সাধারণ জ্ঞান খুঁজে পেতে যাকে একজন অতিথি বলা হয়. ভবিষ্যদ্বাণীর জন্য তার কাছে প্রার্থনা করা এবং তাকে উদ্ধার করা হবে আমার মা যে দুর্বলদের প্রতি ঘৃণা পোষণ করেন, তা নয় । শুনতে এবং প্রার্থনা করতে পারি।","‏ ‏مَضْرُوبٌ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُهْلِكُ أُمَّتِي هَذَا الْحَيُّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَالُوا فَمَا تَأْمُرُنَا يَا رَسُولَ اللَّهِ قَالَ لَوْ أَنَّ النَّاسَ اعْتَزَلُوهُمْ ‏ ‏و قَالَ ‏ ‏أَبِي ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ اضْرِبْ عَلَى هَذَا الْحَدِيثِ فَإِنَّهُ خِلَافُ الْأَحَادِيثِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي قَوْلَهُ اسْمَعُوا وَأَطِيعُوا وَاصْبِرُوا ‏","","",""],[7664,7664,"","আমরা আমাদের অনুপ্রতারিত কামনা দ্বারা তৈরি হয়েছি, যখন আমরা আমার বাবার চেষ্টা করার সময় প্রার্থনা করতে চেষ্টা করেছি। আমার বাবা এমন এক উপহার যা আমি সব প্রার্থনা করে থাকি। ঈশ্বর এর জন্য প্রার্থনা করেছিলেন, আমি আপনাকে ভয় পাচ্ছি","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏سُئِلَ عَنْ قِرَاءَةِ الْإِمَامِ فِي الصَّلَاةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏فِي كُلِّ الصَّلَوَاتِ يُقْرَأُ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَلَيْنَا أَخْفَيْنَا عَلَيْكُمْ ‏","","",""],[7665,7665,"","তিনি আমাকে বলেন, আমি ক্ষমার পর্দার উপর পড়েছি: ঈশ্বরের দোহাইর জন্য শহীদ পুত্রের জন্য আপনার টাকা। আল্লাহ তার কাছে প্রার্থনা করেছেন এবং তাঁর মৃত্যুর সময় তিনি একটি শোভাযাত্রা থেকে আত্মসমর্পণ করবেন। সে আমাকে মেরে ফেলতে চায়, ঈশ্বরের বলে আমাকে পড়তে হবে না, তার জন্য সে বিখ্যাত ছিল এবং সে তার প্রার্থনার সময় নামাজের মুখ দিয়ে তাকে তার বাড়ি পাঠিয়ে দিত। আত্মসমর্পণ করো.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ أُكَيْمَةَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْصَرَفَ مِنْ صَلَاةٍ جَهَرَ فِيهَا بِالْقِرَاءَةِ فَقَالَ ‏ ‏هَلْ قَرَأَ مَعِي أَحَدٌ مِنْكُمْ ‏ ‏آنِفًا ‏ ‏قَالَ ‏ ‏رَجُلٌ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ إِنِّي أَقُولُ مَا لِي ‏ ‏أُنَازَعُ ‏ ‏الْقُرْآنَ قَالَ فَانْتَهَى النَّاسُ عَنْ الْقِرَاءَةِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا جَهَرَ فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْقِرَاءَةِ فِي الصَّلَاةِ حِينَ سَمِعُوا ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[7666,7666,"","তিনি দয়ার ব্রাশে পড়েন: আপনার টাকা আমার বাবার আশীর্বাদের জন্য। আমার বাবা তার কাছে প্রার্থনা করেন। আর উনি বলবেন, ঈশ্বর তাকে না যেতে বলেছেন। ইশ্বর ছাড়া, ঈশ্বরের কাছে, জীবনে সব কিছু আছে, একবারের জন্য ১০ জনের ইতিহাস ছিল, সে শয়তানের কাছ থেকে গার্ড ছিল...","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ فِي يَوْمٍ مِائَةَ مَرَّةٍ كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ وَكُتِبَ لَهُ مِائَةُ حَسَنَةٍ وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ وَكَانَتْ لَهُ ‏ ‏حِرْزًا ‏ ‏مِنْ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ ‏","","",""],[7667,7667,"","সে আমাকে বলেছে, আমার নাম আর বাবার ব্যাপারে আমি তোমার সব থেকে ভালো কিছু পড়েছি, আমার ভালবাসার জন্য। আমি ঈশ্বরের কাছে প্রার্থনা করছি আর সে এটা ছেড়ে দেবে আর বলে দেবে যে ঈশ্বর তাকে একটা জেলে আটকে রাখা হয়েছে। ফাঁপা, চুংস্টোনের মত.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ ‏","","",""],[7668,7668,"","ঈশ্বরের কাছে করা ভবিষ্যদ্বাণী সম্বন্ধে এক গুজবকারী ব্যক্তি একজন দুঃখহীন মানুষের কাছে কিছু বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُوسَى يَعْنِي ابْنَ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مَرْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شَرُّ مَا فِي رَجُلٍ ‏ ‏شُحٌّ ‏ ‏هَالِعٌ ‏ ‏وَجُبْنٌ ‏ ‏خَالِعٌ ‏","","",""],[7669,7669,"","আমার বাবা যখন ঈশ্বরের কথা বলত, তখন আমরা ঈশ্বরের প্রতি তাঁর প্রেম নিয়ে কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏ابْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ رَجُلًا يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَقَالَ وَجَبَتْ قَالُوا يَا رَسُولَ اللَّهِ مَا وَجَبَتْ قَالَ ‏ ‏وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[7670,7670,"","আমার বাবার সবচেয়ে প্রিয় বন্ধুর কথা বলেছিলাম, আমার বাবা ঈশ্বরের কাছে তার কাছে যেতে বলেছেন আর প্রভুর কাছে নিজেকে সমর্পণ করেছেন। ঈশ্বরের দোহাই, ঈশ্বর লিখেছেন, আর তোমার মতো ঈশ্বরকেও যে এটা করতে পারে বলে...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ اصْطَفَى مِنْ الْكَلَامِ أَرْبَعًا سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ فَمَنْ قَالَ سُبْحَانَ اللَّهِ كَتَبَ اللَّهُ لَهُ عِشْرِينَ حَسَنَةً أَوْ حَطَّ عَنْهُ عِشْرِينَ سَيِّئَةً وَمَنْ قَالَ اللَّهُ أَكْبَرُ فَمِثْلُ ذَلِكَ وَمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَمِثْلُ ذَلِكَ وَمَنْ قَالَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ مِنْ قِبَلِ نَفْسِهِ كُتِبَتْ لَهُ ثَلَاثُونَ حَسَنَةً وَحُطَّ عَنْهُ ثَلَاثُونَ سَيِّئَةً ‏","","",""],[7671,7671,"","আমরা একটি ভাস্কর্যের দ্বারা রক্ষা হয়েছি একটি ঘোড়ার বাপ্তিস্মের জন্য এবং একটি ভাইয়ের বিচার করা হয়েছে যখন একটি ভাই একটি ঘোড়া যে একটি জিনিয়াস যে তিনি পিতা শুনতে পারে শুনতে পারে ( হিতোপদেশ ১৪: ৩) ঈশ্বরকে বলতে হবে যে, তিনি হয়তো বলতে পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَجِبَ رَبُّنَا مِنْ قَوْمٍ يُقَادُونَ إِلَى الْجَنَّةِ فِي السَّلَاسِلِ ‏","","",""],[7672,7672,"","আমরা আমাদের সব থেকে ভালো কথা বলেছি... ...যে আমরা শুনেছি সে-ই... ...যে কিনা মুক্ত-অনুবাদক শিকারী, ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে আত্মসমর্পণ করবে যদি আমি তার অনুসন্ধান থেকে তাকে খেতে বলি!","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِطَعَامٍ مِنْ غَيْرِ أَهْلِهِ سَأَلَ عَنْهُ فَإِنْ قِيلَ هَدِيَّةٌ أَكَلَ وَإِنْ قِيلَ ‏ ‏صَدَقَةٌ ‏ ‏قَالَ كُلُوا وَلَمْ يَأْكُلْ ‏","","",""],[7673,7673,"","আমরা কথা বলেছি, আমরা যা শুনেছি তা নিয়ে কথা বলেছি, ঈশ্বর বলতে হবে যে সে শহরের বাইরে আছে, তার জন্য সে ঈশ্বরের জন্য অনেক ভালো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏رِجَالٌ رَغْبَةً عَنْهَا ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ ‏","","",""],[7674,7674,"","আমরা আমাদের সবচেয়ে ভালো কথা বলেছি, আমি এমন একজনের কথা শুনেছি যার কথা আমি কখনো শুনিনি। ডিপার্টমেন্ট তার জন্য প্রার্থনা করেছিল এবং সে বলবে যে সে আমার মায়ের সেবায় প্রবেশ করবে, তার কন্যা। পাগলের মত, তারপর আরেকজন বললো ভগবান যেন আমাকে বলে যে, তোমাকে মেরে ফেল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَدْخُلُ سَبْعُونَ أَلْفًا مِنْ أُمَّتِي الْجَنَّةَ بِغَيْرِ حِسَابٍ فَقَالَ رَجُلٌ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ ثُمَّ قَامَ آخَرُ فَقَالَ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏","","",""],[7675,7675,"","তিনি বলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং তাঁর হাতে যে পাপ রয়েছে, তা তিনি দূর করে দেবেন । আমার বাবার কাছে এমন একটা উপহার রয়েছে, যা আগে কখনো জিজ্ঞেস করিনি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخُطْبَةُ الَّتِي لَيْسَ فِيهَا شَهَادَةٌ كَالْيَدِ ‏ ‏الْجَذْمَاءِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمِنْهَالِ ‏ ‏أَخُو ‏ ‏حَجَّاجٍ الْأَنْمَاطِيُّ ‏ ‏وَكَانَ ثِقَةً ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِثْلَهُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[7676,7676,"","আমরা আমাদের দেখা সবচেয়ে ভালো কথা বলেছি, ভালোটা আমার ছেলের স্বপ্নের স্বপ্ন, সে আত্মসমর্পণ করেছে এবং বলেছে যে সে কখনো মানুষকে না বলার জন্য ঈশ্বরকে ধন্যবাদ জানায়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏الرَّبِيعُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏الْعَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ ‏","","",""],[7677,7677,"","তিনি আমাকে বলেন, আমি ক্ষমার পর্দার উপর পড়েছি: আপনার টাকা আমার বাবার জন্য আমার বাবার ভালবাসার জন্য সালাদে যাচ্ছে, ঈশ্বর আমাদের বললেন যদি তাকে খেলার জন্য খেলতে হয়। অথবা রাস্তা থেকে সরে যাওয়ার শেষ জল সঙ্গে সঙ্গে সঙ্গে এর নিজের চোখকে জল বা তার সঙ্গে সঙ্গে রাখে ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ ‏ ‏أَوْ الْمُؤْمِنُ ‏ ‏فَغَسَلَ وَجْهَهُ خَرَجَتْ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنِهِ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ أَوْ نَحْوَ هَذَا ‏ ‏فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ مِنْ يَدَيْهِ كُلُّ خَطِيئَةٍ بَطَشَ بِهَا مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ ‏ ‏حَتَّى يَخْرُجَ نَقِيًّا مِنْ الذُّنُوبِ ‏","","",""],[7678,7678,"","ঈশ্বর আমার বাবাকে আশীর্বাদ করেন এবং আপনাকে তা জানাতে পারবেন না । গবাদি পশুর ক্ষমতা বহন করার জন্য আলো দিয়ে সিগারেটের সিগারেট তৈরি করা ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِمَا يَمْحُو اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ ‏ ‏إِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى ‏ ‏الْمَكَارِهِ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فِي ‏ ‏الْمَكَارِهِ ‏ ‏وَكَثْرَةُ الْخُطَى إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏","","",""],[7679,7679,"","তিনি দয়ার ব্রাশে পড়েন: আমার বাবার আশীর্বাদের জন্য আপনার টাকা আমার বাবার কাছে দান। আমার বাবা এমন একটা উপহার যেটা তার কাছে প্রার্থনা করেন এবং যদি মানুষ জানতে পারে যে কি ফোন আর কি কল করতে হবে তারা বুঝতে পারবে না তারা কি শিখতে চায়, এবং অন্ধকার এমনকি গণনাও করে না।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ ‏ ‏يَسْتَهِمُوا ‏ ‏عَلَيْهِ ‏ ‏لَاسْتَهَمُوا ‏ ‏عَلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ ‏ ‏حَبْوًا ‏","","",""],[7680,7680,"","আমরা বাবার সর্বোচ্চ দুই বছরের স্যর প্রভুর ব্যাপারে কথা বলেছি, ঈশ্বর তাকে প্রার্থনা করেন এবং বলবে ঈশ্বর ঈশ্বর ঈশ্বর এই শপথের জন্য ঈশ্বরের কাছে যাবেন না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏أَبِي رُهْمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رُبَّ يَمِينٍ لَا تَصْعَدُ إِلَى اللَّهِ بِهَذِهِ الْبُقْعَةِ فَرَأَيْتُ فِيهَا ‏ ‏النَّخَّاسِينَ ‏ ‏بَعْدُ ‏","","",""],[7681,7681,"","সে বলেছে আমার ছেলে, আমার বাবার ব্যাপারে, আমার ভাই, তার ঈশ্বর সম্পর্কে আমি তোমার সব থেকে ভালো কিছু পড়েছি। ঈশ্বর বলতেই হবে তুমি আমার সামনে থাকবে এবং তুমি কি ভয় পাও তা দেখে রাখতে পার। - কেন?","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَلْ تَرَوْنَ قِبْلَتِي هَاهُنَا فَوَاللَّهِ مَا ‏ ‏يَخْفَى عَلَيَّ خُشُوعُكُمْ وَلَا رُكُوعُكُمْ إِنِّي لَأَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي ‏","","",""],[7682,7682,"","এক বছর আগে আমার বাবা মদ খেয়ে তার জন্য প্রার্থনা করেছিলেন এবং তিনি বলবেন যে তিনি তাঁর ইচ্ছার দ্বারা আশীর্বাদ হবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ لُدَيْنٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ يَوْمَ الْجُمُعَةِ يَوْمُ عِيدٍ فَلَا تَجْعَلُوا يَوْمَ عِيدِكُمْ يَوْمَ صِيَامِكُمْ إِلَّا أَنْ تَصُومُوا قَبْلَهُ أَوْ بَعْدَهُ ‏","","",""],[7683,7683,"","আমরা তোমার বাবার সবচেয়ে ভালো কথা বলেছি যে আমরা তোমার জীবন জয় করার চেষ্টা করেছি। আমার বাবার সবচেয়ে ভালো চাওয়া, ঈশ্বরের ইচ্ছা জানতে চাইলে তাকে জিজ্ঞেস করতে হবে। রাতের মুখে প্রার্থনা করো যেখানে আমি প্রভুর বিখ্যাত হওয়ার পর কোন মাছটা বেশি পছন্দ করি","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الصَّلَاةِ أَفْضَلُ بَعْدَ الْمَكْتُوبَةِ قَالَ الصَّلَاةُ فِي جَوْفِ اللَّيْلِ قِيلَ أَيُّ الصِّيَامِ أَفْضَلُ بَعْدَ رَمَضَانَ قَالَ شَهْرُ اللَّهِ الَّذِي تَدْعُونَهُ الْمُحَرَّمَ ‏","","",""],[7684,7684,"","আমার বাবা হলেন উপহার আর বাবা তাঁর বধির সন্তানদের কাছে প্রার্থনা করতে পেরে খুশি এবং যা যা বলা যায় তা তিনি তুলে ধরতে পারবেন । ভুল, তারা দুঃখ পায় না এবং তারা আহত হয় না, এমনকি তারা অন্ধকারও নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يُصِيبُ الْمُؤْمِنَ مِنْ ‏ ‏وَصَبٍ ‏ ‏وَلَا ‏ ‏نَصَبٍ ‏ ‏وَلَا هَمٍّ وَلَا حَزَنٍ وَلَا أَذًى وَلَا غَمٍّ حَتَّى الشَّوْكَةُ يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ مِنْ خَطَايَاهُ ‏","","",""],[7685,7685,"","আমার বাবা ঈশ্বরের কাছে অনুরোধ করেছিলেন যেন তিনি তাকে ব্যর্থ না করেন এবং ঈশ্বরের কাছে ফিরে যান ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَمُؤَمَّلٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏مُؤَمَّلٌ ‏ ‏الْخُرَاسَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ وَرْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ عَلَى دِينِ خَلِيلِهِ فَلْيَنْظُرْ أَحَدُكُمْ مَنْ يُخَالِطُ ‏ ‏وَقَالَ ‏ ‏مُؤَمَّلٌ ‏ ‏مَنْ ‏ ‏يُخَالِلُ ‏","","",""],[7686,7686,"","আমরা আমার বাবা ভালো ছেলে হওয়া সম্পর্কে কথা বলেছি, তার জন্য প্রার্থনা করা উচিত ছিল। তুমি কি জানো ঐ শয়তানগুলো আমাদের সাথে বসে কে বলেছিল, প্রভু, কে জানে না তারা কারা ছিল বা তারা কী বলেছে? মূল্যবোধ নিরব হয়ে গেছে আর হারিয়ে গেছে, তার বছর থেকে, আমার পরিকল্পনা থেকে সে তার কাছ থেকে যা পেয়েছে তা হারার আগেই সে জিতে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَلْ تَدْرُونَ مَنْ الْمُفْلِسُ قَالُوا الْمُفْلِسُ فِينَا يَا رَسُولَ اللَّهِ مَنْ لَا دِرْهَمَ لَهُ وَلَا مَتَاعَ قَالَ ‏ ‏إِنَّ الْمُفْلِسَ مِنْ أُمَّتِي مَنْ يَأْتِي يَوْمَ الْقِيَامَةِ بِصِيَامٍ وَصَلَاةٍ وَزَكَاةٍ وَيَأْتِي قَدْ شَتَمَ عِرْضَ هَذَا وَقَذَفَ هَذَا وَأَكَلَ مَالَ هَذَا فَيُقْعَدُ ‏ ‏فَيَقْتَصُّ ‏ ‏هَذَا مِنْ حَسَنَاتِهِ وَهَذَا مِنْ حَسَنَاتِهِ فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ يَقْضِيَ مَا عَلَيْهِ مِنْ الْخَطَايَا أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ ثُمَّ طُرِحَ فِي النَّارِ ‏","","",""],[7687,7687,"","আমার বাবার প্রতি করুণা দেখানোর কথা বলেছিলাম, আমার ছেলের সাথে উড়তে গিয়ে লর্ড প্যাডরের যেভাবে আমাদের সবচেয়ে পবিত্র মানুষ হবে, তার চেয়ে বেশি কিছু করতে হবে। তার ঋণ বিক্রি করে দেন, কিছু টাকা। ডিএনএ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا بِالْأَعْمَالِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا ‏ ‏وَيُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا يَبِيعُ دِينَهُ بِعَرَضٍ مِنْ الدُّنْيَا قَلِيلٍ ‏","","",""],[7688,7688,"","তিনি আমাকে দেখতে আসার চেষ্টা করার কথা বলেছিলেন । বাবার জ্ঞান আর বলে যে তার এই ভুলের প্রতি তার করুণা আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَوْشَبُ بْنُ عَقِيلٍ ‏ ‏حَدَّثَنِي ‏ ‏مَهْدِيٌّ ‏ ‏حَدَّثَنِي ‏ ‏عِكْرِمَةُ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي بَيْتِهِ فَسَأَلْتُهُ عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏بِعَرَفَاتٍ ‏ ‏فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏بِعَرَفَاتٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَهْدِيٍّ الْعَبْديِّ ‏","","",""],[7689,7689,"","আমরা একটা পাথরের কথা বলেছিলাম যে সে হয়তো মুক্ত হবে, ঈশ্বর যদি আমাদের আর বিক্রি না করি তাহলে তাকে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسِ بْنِ عَمْرٍو الْهَجَرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏لَمْ ‏ ‏يَخْنَزْ ‏ ‏اللَّحْمُ وَلَمْ يَخْبُثْ الطَّعَامُ وَلَوْلَا ‏ ‏حَوَّاءُ ‏ ‏لَمْ تَخُنْ أُنْثَى زَوْجَهَا ‏","","",""],[7690,7690,"","আমি আমার ভালবাসা সম্বন্ধে শুনেছি, আমার মা তার কাছে প্রার্থনা করেছিল এবং বলতে শুরু করেছিল যে, আমার মা তার হাত জিতবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ظَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ حِبِّي ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ فَسَادَ أُمَّتِي عَلَى يَدَيْ غِلْمَةٍ ‏ ‏سُفَهَاءَ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏","","",""],[7691,7691,"","আমরা আমার বাবার সাথে দেখা হওয়া এক যুবক বাবার কথা বলেছিলাম, নাবিকের সাথে কথা বলতে গিয়ে, কিন্তু তার ভালো অনুভূতি আছে। ভাল হবে আর তার সাথে মানুষ খুজে বের করবে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ ‏ ‏النَّجْمَ ‏ ‏فَسَجَدَ وَسَجَدَ النَّاسُ مَعَهُ إِلَّا رَجُلَيْنِ أَرَادَا الشُّهْرَةَ ‏","","",""],[7692,7692,"","আমার বাবা এমন এক উপহার, যা ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং একজন মহিলার মাধ্যমে তিনি তা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَلْقَمَةَ يَعْنِي الْفَرْوِيَّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ أَصَابَتْ بَخُورًا فَلَا تَشْهَدَنَّ عِشَاءَ الْآخِرَةِ ‏","","",""],[7693,7693,"","আমরা এক মাসের আগুন দিয়ে আমাদের যথাসাধ্য করার কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ حُسْنَ الظَّنِّ مِنْ حُسْنِ الْعِبَادَةِ ‏","","",""],[7694,7694,"","আমরা আমাদের সময়ের সর্বোত্তমটা নিয়ে কথা বলেছি, অথবা আল্লাহ তার কাছে প্রার্থনা করেছে যেন তারা তার কাছে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏ثُمَامَةَ بْنَ أُثَالٍ ‏ ‏أَوْ ‏ ‏أُثَالَةَ ‏ ‏أَسْلَمَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبُوا بِهِ إِلَى حَائِطِ بَنِي فُلَانٍ فَمُرُوهُ أَنْ يَغْتَسِلَ ‏","","",""],[7695,7695,"","আমরা আমার ছেলেকে হারানোর কথা বলেছিলাম, কিন্তু সে তোমাকে ভুলে যায়নি, আমার বাবা ভবিষ্যদ্বাণীর উপহার... ...যে তাকে আদেশ দিয়েছে... হে পালনকর ্ তা ! তুমি তাকে তোমার দয়া থেকে উদ ্ ধার কর অথবা তোমার মহিমার সাথে বলো না --","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ يَعْنِي ابْنَ أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُرْسِلَ عَلَى ‏ ‏أَيُّوبَ ‏ ‏جَرَادٌ مِنْ ذَهَبٍ فَجَعَلَ يَلْتَقِطُ فَقَالَ أَلَمْ أُغْنِكَ يَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ يَا رَبِّ وَمَنْ يَشْبَعُ مِنْ رَحْمَتِكَ ‏ ‏أَوْ قَالَ مِنْ فَضْلِكَ ‏","","",""],[7696,7696,"","আমি আমার বাবার মতো আশাবাদী ব্যক্তি, আমার বাবার কাছে একটা ভাগ্যের কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَتْ شَجَرَةٌ تُؤْذِي أَهْلَ الطَّرِيقِ فَقَطَعَهَا رَجُلٌ فَنَحَّاهَا عَنْ الطَّرِيقِ فَأُدْخِلَ بِهَا الْجَنَّةَ ‏","","",""],[7697,7697,"","আমরা আমার বাবাকে আশাবাদী ব্যক্তি হিসেবে প্রমাণ করেছি যে তার বাবার ভাগ্য প্রমাণ করেছে। আমি যা করতে পারি তা ভালো কাজ, যা তারা কখনো করতে পারবে না। এক নরকে তারা তোমাকে করেছে, তাই আল্লাহ্‌ বলেছেন, এটা জয় হয়েছে এবং কখনোই হবে না। তোমার ভয় যেন বলে যে ওকে ক্ষমা করে দেওয়া হয়নি","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَغَيْرُ وَاحِدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَابْنِ سِيرِينَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ رَجُلٌ مِمَّنْ كَانَ قَبْلَكُمْ لَمْ يَعْمَلْ خَيْرًا قَطُّ إِلَّا التَّوْحِيدَ فَلَمَّا احْتُضِرَ قَالَ لِأَهْلِهِ انْظُرُوا إِذَا أَنَا مِتُّ أَنْ يُحْرِقُوهُ حَتَّى يَدَعُوهُ حُمَمًا ثُمَّ اطْحَنُوهُ ثُمَّ اذْرُوهُ فِي يَوْمِ رِيحٍ فَلَمَّا مَاتَ فَعَلُوا ذَلِكَ بِهِ فَإِذَا هُوَ فِي قَبْضَةِ اللَّهِ فَقَالَ اللَّهُ عَزَّ وَجَلَّ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا حَمَلَكَ عَلَى مَا فَعَلْتَ قَالَ أَيْ رَبِّ مِنْ مَخَافَتِكَ قَالَ فَغُفِرَ لَهُ بِهَا وَلَمْ يَعْمَلْ خَيْرًا قَطُّ إِلَّا التَّوْحِيدَ ‏","","",""],[7698,7698,"","আমার বাবার স্বপ্নের কথা বলছিলাম আমার বাবার মুক্তির স্বপ্ন সম্পর্কে। ঈশ্বর তাকে এমন একজন লোককে দেখেছেন যে শপথ নিতে রাজি যে এটা বলতে পারবে যে সে পছন্দ করে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا مُضْطَجِعًا عَلَى بَطْنِهِ فَقَالَ ‏ ‏إِنَّ هَذِهِ ضِجْعَةٌ لَا يُحِبُّهَا اللَّهُ ‏","","",""],[7699,7699,"","ঈশ্বর আমাদের প্রার্থনা শুনেছিলেন এবং আমাদের ছেলেকে বাইবেল অধ্যয়ন করার জন্য পাঠিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَا ‏ ‏الْعَاصِ ‏ ‏مُؤْمِنَانِ ‏ ‏عَمْرٌو ‏ ‏وَهِشَامٌ ‏","","",""],[7700,7700,"","আমরা বাবা - মা পূর্ণ - সময়ের প্রচার কাজ শুরু করেছিলাম । বিদায়, আমরা শেষ কথা বলেছিলাম, যদি আমরা মারা যাই, তাহলে আমি শুধু তাই করবো, আমি চাই তুমি ঈশ্বরের কাছে যা যাও, ঈশ্বরের কাছে, তার সাথে যা ঘটেছে, সেটা হলো একটা শিকারীকে নিয়ে যাওয়া আর তা পূর্ণ করতে দেওয়া। সে যেন তাকে ছেড়ে না দেয় এবং তাকে ছেড়ে না দেয়। মেঘের ভেতর দিয়ে তাদের কাছে গিয়ে বলতে হবে যে খোদা জিতবে না, আমাদের একজন অতিথি এসেছে, আমরা শ্রেষ্ঠ প্রভুর চেয়ে ভালো কাজ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدٌ الطَّائِيُّ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏سَعْدٌ أَبُو مُجَاهِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُدِلَّةِ ‏ ‏مَوْلَى أُمِّ الْمُؤْمِنِينَ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ إِنَّا إِذَا رَأَيْنَاكَ رَقَّتْ قُلُوبُنَا ‏ ‏وَكُنَّا مِنْ أَهْلِ الْآخِرَةِ وَإِذَا فَارَقْنَاكَ أَعْجَبَتْنَا الدُّنْيَا وَشَمَمْنَا النِّسَاءَ وَالْأَوْلَادَ قَالَ ‏ ‏لَوْ تَكُونُونَ ‏ ‏أَوْ قَالَ لَوْ أَنَّكُمْ تَكُونُونَ ‏ ‏عَلَى كُلِّ حَالٍ عَلَى الْحَالِ الَّتِي أَنْتُمْ عَلَيْهَا عِنْدِي لَصَافَحَتْكُمْ الْمَلَائِكَةُ بِأَكُفِّهِمْ وَلَزَارَتْكُمْ فِي بُيُوتِكُمْ وَلَوْ لَمْ تُذْنِبُوا لَجَاءَ اللَّهُ بِقَوْمٍ يُذْنِبُونَ كَيْ يَغْفِرَ لَهُمْ قَالَ قُلْنَا يَا رَسُولَ اللَّهِ حَدِّثْنَا عَنْ الْجَنَّةِ مَا بِنَاؤُهَا قَالَ ‏ ‏لَبِنَةُ ‏ ‏ذَهَبٍ ‏ ‏وَلَبِنَةُ ‏ ‏فِضَّةٍ ‏ ‏وَمِلَاطُهَا ‏ ‏الْمِسْكُ ‏ ‏الْأَذْفَرُ ‏ ‏وَحَصْبَاؤُهَا اللُّؤْلُؤُ وَالْيَاقُوتُ وَتُرَابُهَا الزَّعْفَرَانُ مَنْ يَدْخُلُهَا يَنْعَمُ وَلَا يَبْأَسُ وَيَخْلُدُ وَلَا يَمُوتُ لَا ‏ ‏تَبْلَى ثِيَابُهُ وَلَا ‏ ‏يَفْنَى شَبَابُهُ ثَلَاثَةٌ لَا تُرَدُّ دَعْوَتُهُمْ الْإِمَامُ الْعَادِلُ وَالصَّائِمُ حَتَّى يُفْطِرَ وَدَعْوَةُ الْمَظْلُومِ تُحْمَلُ عَلَى الْغَمَامِ وَتُفْتَحُ لَهَا أَبْوَابُ السَّمَاءِ وَيَقُولُ الرَّبُّ عَزَّ وَجَلَّ وَعِزَّتِي لَأَنْصُرَنَّكَ وَلَوْ بَعْدَ حِينٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ عُبَيْدٍ الطَّائِيُّ ‏ ‏قُلْتُ ‏ ‏لِزُهَيْرٍ ‏ ‏أَهُوَ ‏ ‏أَبُو الْمُجَاهِدِ ‏ ‏قَالَ نَعَمْ قَدْ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْمُدِلَّةِ ‏ ‏مَوْلَى أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[7701,7701,"","আমরা আমাদের বাবা জোন্সের কথা বলেছিলাম, যিনি ঈশ্বরের দ্বারা পাস করেছেন, তার মানে আমার ছেলে একজন ভাববাদী, তিনি ঈশ্বর তাকে আদেশ দিয়েছেন আর আমি তাকে তার কাছে পৌঁছে দেব যে তোমাকে মারতে হবে, আমি তোমাকে খুন করবো। তুমি যে বাড়িতে আছ সেটা না যে বাড়িতে ছিল সেটা একজন মহান মানুষ. আদর্শবানকে শিকার করা হয় ... এবং এই স্টান্টের রহস্য দ্বারা চালিত হয়. আর তিনি আত্মসমর্পণ করিবেন, তারপর কুকুরদের আরও ভাল সেবা প্রদান করা হবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ عَمْرِو بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ إِنِّي كُنْتُ أَتَيْتُكَ اللَّيْلَةَ فَلَمْ يَمْنَعْنِي أَنْ أَدْخُلَ عَلَيْكَ الْبَيْتَ الَّذِي أَنْتَ فِيهِ إِلَّا أَنَّهُ كَانَ فِي الْبَيْتِ تِمْثَالُ رَجُلٍ وَكَانَ فِي الْبَيْتِ ‏ ‏قِرَامُ ‏ ‏سِتْرٍ فِيهِ تَمَاثِيلُ فَمُرْ بِرَأْسِ التِّمْثَالِ يُقْطَعْ فَيُصَيَّرَ كَهَيْئَةِ الشَّجَرَةِ وَمُرْ بِالسِّتْرِ يُقْطَعْ فَيُجْعَلَ مِنْهُ وِسَادَتَانِ ‏ ‏تُوطَآَنِ ‏ ‏وَمُرْ بِالْكَلْبِ فَيُخْرَجَ فَفَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا الْكَلْبُ ‏ ‏جَرْوٌ ‏ ‏كَانَ ‏ ‏لِلْحَسَنِ ‏ ‏وَالْحُسَيْنِ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏تَحْتَ ‏ ‏نَضَدٍ ‏ ‏لَهُمَا قَالَ وَمَا زَالَ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ ‏ ‏أَوْ رَأَيْتُ ‏ ‏أَنَّهُ سَيُوَرِّثُهُ ‏","","",""],[7702,7702,"","আমরা বাবার কাছে বাবার একটা ভোদাইমামামা ছিল, ঈশ্বরের ইচ্ছা হল তার কাছে প্রার্থনা করা আর তিনি আত্মসমর্পণ করেছেন যে ঈশ্বর তাঁর অনুগতদের চোখে জিতে গেছেন. অদ্ভুত।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏وَإِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ أَبِي الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏لَيُبَاهِي الْمَلَائِكَةَ بِأَهْلِ ‏ ‏عَرَفَاتٍ ‏ ‏يَقُولُ انْظُرُوا إِلَى عِبَادِي ‏ ‏شُعْثًا ‏ ‏غُبْرًا ‏","","",""],[7703,7703,"","আমরা আমার বাবা বিড়ালের ব্যাপারে কথা বলেছি যে ঈশ্বর তার হাত ধরে নিয়ে কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الدَّوَاءِ الْخَبِيثِ ‏","","",""],[7704,7704,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর মৃত্যুর বিষয়ে তাঁর নিজের জ্ঞান লাভ করার জন্য তাঁকে প্রার্থনা করেছেন । অনেক বছর ধরে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ أُلْجِمَ بِلِجَامٍ مِنْ نَارٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[7705,7705,"","আমি যদি গলি থেকে এসে থাকি, তাহলে আমি এটা জিজ্ঞেস করব, এটা কি কোন উপহার নাকি একটা সময়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِطَعَامٍ مِنْ غَيْرِ أَهْلِهِ سَأَلَ عَنْهُ فَإِنْ قِيلَ هَدِيَّةٌ أَكَلَ وَإِنْ قِيلَ ‏ ‏صَدَقَةٌ ‏ ‏قَالَ كُلُوا وَلَمْ يَأْكُلْ ‏","","",""],[7706,7706,"","আমরা বাবা আর আমরা এক মাস কাঠের কথা বলেছিলাম। ঈশ্বরের ইচ্ছার সাথে বের হয়ে যাও, আর ওকে চেষ্টা কর, আর ওরা এই গাছের মধ্যে ধরা পড়বে। আমরা তাকে ঈশ্বরের কাছে নিয়ে যাব, স্বর্গ থেকে বক্ররেখা বের করে দেব আর এটা শীতের বিষের মতো।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ أَبِي وَحْشِيَّةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَصْحَابِهِ وَهُمْ يَتَنَازَعُونَ فِي هَذِهِ الشَّجَرَةِ الَّتِي اجْتُثَّتْ مِنْ فَوْقِ الْأَرْضِ مَا لَهَا مِنْ قَرَارٍ فَقَالُوا نَحْسَبُهَا ‏ ‏الْكَمْأَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ وَالْعَجْوَةُ مِنْ الْجَنَّةِ وَهِيَ شِفَاءٌ مِنْ السُّمِّ ‏","","",""],[7707,7707,"","আমরা কথা বলেছিলাম আমার বাবা কুমারী ছিলেন, সে ঈশ্বরের অনুগ্রহের যাজকবর্গকে হারিয়ে ফেলেছে, ঈশ্বর তাকে তার সমস্ত প্রাণ দিয়ে শিখিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا قَفَّا ‏ ‏وَفْدُ عَبْدِ الْقَيْسِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ امْرِئٍ حَسِيبُ نَفْسِهِ لِيَنْتَبِذْ كُلُّ قَوْمٍ فِيمَا بَدَا لَهُمْ ‏","","",""],[7708,7708,"","আমরা জয় করেছি। আমাদের একটা বাপ্তিস্ম আছে যা আমার হাত মুছে দেবে। আমার বাবা তাকে বলতে বাধ্য করেছেন যে ঈশ্বর তাকে আদেশ দিয়েছেন আর ঈশ্বর বলছেন যে ঈশ্বর বলছেন যে, এবং যে তা অন ্ তরে প ্ রত ্ যাবর ্ তন করে , তার উপর রয়েছে নিজের পক ্ ষ থেকে আগত একের আযাব । আর আমি প্রতিজ্ঞা করছি, তুমি শিখতে পারবে বা ভান করতে পারবে।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ ‏","","",""],[7709,7709,"","আমরা এমন এক লোকের সাথে কথা বলেছি, যে আমাদের জন্য এক ছেলেকে দিয়ে দিয়ে দিয়ে সে একটা ছেলেকে রক্ষা করবে। আমার বাবা যখন ঈশ্বরের কাছে একজন জিনিয়াস, ঈশ্বর তাকে আদেশ দিয়েছেন এবং তার আছে, তখন সে আমাদের এক সন্তান হিসেবে রক্ষা করবে। ( মথি ৫: ৩, ৪) আগামীকাল জগৎ পুরস্কৃত হয় এবং অন্য আরেক দরজা দিয়ে ভর করে বলা হয় প্রভু ভুল করেছেন এবং সক্রিয় আছেন ।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مَلَكًا بِبَابٍ مِنْ أَبْوَابِ السَّمَاءِ يَقُولُ مَنْ يُقْرِضْ الْيَوْمَ ‏ ‏يُجْزَى غَدًا ‏ ‏وَمَلَكًا بِبَابٍ آخَرَ يَقُولُ اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا وَعَجِّلْ لِمُمْسِكٍ تَلَفًا ‏","","",""],[7710,7710,"","আমি আমার ভাইয়ের ভালোবাসা নিয়ে কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন যে, তিনি তার তলোয়ারে পঞ্চমটি নিয়ে গেছেন। সর্বশেষটি পানিতে বসে আছে। এরপর তিনি সেই মহিলাকে বিক্রি করে দেন এবং চলে যান ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ رَجُلًا حَمَلَ مَعَهُ خَمْرًا فِي سَفِينَةٍ يَبِيعُهُ وَمَعَهُ قِرْدٌ قَالَ فَكَانَ الرَّجُلُ إِذَا بَاعَ الْخَمْرَ شَابَهُ بِالْمَاءِ ثُمَّ بَاعَهُ قَالَ فَأَخَذَ الْقِرْدُ الْكِيسَ فَصَعِدَ بِهِ فَوْقَ ‏ ‏الدَّقَلِ ‏ ‏قَالَ فَجَعَلَ يَطْرَحُ دِينَارًا فِي الْبَحْرِ وَدِينَارًا فِي السَّفِينَةِ حَتَّى قَسَمَهُ ‏","","",""],[7711,7711,"","আমার ভাই হারলি আমরা একটা পছন্দ করেছি কিভাবে একটি বড় মুখ দিয়ে শেষ করতে হয়। আমার লেখকরা এসব অনুষ্ঠান করতে যাচ্ছে আর আমার মনে হয় না একটা ছেলেকে হারানোর কথা ঈশ্বর তার কাছে প্রার্থনা করেছিলেন এবং তাকে আত্মসমর্পণ করবেন, যিনি সকালে হাঁটু গেড়ে প্রার্থনা করেছিলেন এবং এরপর তার প্রার্থনার মাধ্যমে সূর্যকে উপাসনা করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏وَجَدْتُ فِي كِتَابِي ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏وَلَا أَظُنُّهُ إِلَّا ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى رَكْعَةً مِنْ الصُّبْحِ ثُمَّ طَلَعَتْ الشَّمْسُ فَلْيُتِمَّ صَلَاتَهُ ‏","","",""],[7712,7712,"","আমরা একটা স্বপ্নের কথা বলেছি, যার মানে, একবার কথা বলার পর একটা ছেলেও তাকে শিক্ষা দিয়েছে আর সে বলবে যে আমি তোমার প্রভুর কাছে লর্ড।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمٌ يَعْنِي ابْنَ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ مِينَاءَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[7713,7713,"","আমরা দুটো বিষয় নিয়ে কথা বলেছি, কিন্তু আমার মনে হয় আমাদের হারিয়ে যেতে হবে। আমার বাবা আমার কাছে ঈশ্বরের কাছে একটি উপহার আছে। যিনি শক ্ তিশালী , বিশ ্ বজগতের পালনকর ্ তা ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏وَلَا أَظُنُّهُ إِلَّا ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[7714,7714,"","আমি যখন আমার বাবার সঙ্গে কথা বলেছিলাম, তখন আমি তাকে বলেছিলাম যে ঈশ্বর কখনো তা করবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّوْمُ جُنَّةٌ فَإِذَا كَانَ أَحَدُكُمْ يَوْمًا صَائِمًا فَلَا يَرْفُثْ وَلَا يَجْهَلْ فَإِنْ امْرُؤٌ شَتَمَهُ أَوْ قَاتَلَهُ فَلْيَقُلْ إِنِّي صَائِمٌ ‏","","",""],[7715,7715,"","বাবা আমাদের জন্য ভাববাদীর কাছে প্রার্থনা করেছিলেন আর আমরা যখন একটা আলবি বা একটা সময়ে পৌঁছে যাব, তখন তাকে একটা শপথ করে বলি । আমরা ওদের হাতে মারব আর মেরে ফেলবো শুধু মেরেই আমাদের খুন করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَزِّمِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَاسْتَقْبَلْنَا ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏فَاسْتَقْبَلَنَا ‏ ‏رِجْلٌ مِنْ جَرَادٍ فَجَعَلْنَا نَضْرِبُهُنَّ بِعِصِيِّنَا ‏ ‏وَسِيَاطِنَا ‏ ‏وَنَقْتُلُهُنَّ وَأُسْقِطَ فِي أَيْدِينَا فَقُلْنَا مَا نَصْنَعُ وَنَحْنُ مُحْرِمُونَ فَسَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا بَأْسَ بِصَيْدِ الْبَحْرِ ‏","","",""],[7716,7716,"","তিনি তার জন্য প্রার্থনা করেছিলেন এবং বলবেন যে, যারা সমাজকে যুদ্ধ করে চলে গিয়েছে এবং তিনি পথ ছেড়ে চলে গেছেন, তারা চলে গিয়েছে । তার বিরুদ্ধে এবং আমার মাস্টারকে ছেড়ে দেয়া হবে না। তুমি চোখ নাড়াবে, তুমি রেগে যাচ্ছ, নাকি তুমি কল্পনার জোরে মারছো নাকি হরিণের মত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ رِيَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ فَارَقَ الْجَمَاعَةَ وَخَرَجَ مِنْ الطَّاعَةِ فَمَاتَ فَمِيتَتُهُ جَاهِلِيَّةٌ وَمَنْ خَرَجَ عَلَى أُمَّتِي بِسَيْفِهِ يَضْرِبُ بَرَّهَا وَفَاجِرَهَا لَا ‏ ‏يُحَاشِي مُؤْمِنًا لِإِيمَانِهِ وَلَا يَفِي لِذِي عَهْدٍ بِعَهْدِهِ فَلَيْسَ مِنْ أُمَّتِي وَمَنْ قُتِلَ تَحْتَ رَايَةٍ ‏ ‏عِمِّيَّةٍ يَغْضَبُ لِلْعَصَبِيَّةِ أَوْ يُقَاتِلُ لِلْعَصَبِيَّةِ أَوْ يَدْعُو إِلَى الْعَصَبِيَّةِ فَقِتْلَةٌ جَاهِلِيَّةٌ ‏","","",""],[7717,7717,"","আমি আমার বাবার সবচেয়ে ভালটার কথা বলেছিলাম... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সকল মানুষের দুষ্টতার কারণে তিনি বেঁচে থাকবেন. তাদের দেখতে যে সে বেঁচে আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْسِرُ الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ فَيَقْتَتِلُ النَّاسُ فَيُقْتَلُ مِنْ كُلِّ مِائَةٍ تِسْعُونَ ‏ ‏أَوْ قَالَ تِسْعَةٌ وَتِسْعُونَ ‏ ‏كُلُّهُمْ يَرَى أَنَّهُ يَنْجُو ‏","","",""],[7718,7718,"","আমি যখন তাকে বলেছিলাম যে, সে যেন তার হাত কেটে না ফেলে । আমি তাকে মারতে হেরেছি, আমি তাকে পছন্দ করি, যে কিনা তোমাকে সবচেয়ে ভালো বলেছে যখন সে চলে যাবে আর হয়তো সে ভালো আছে। লর্ড তার কাছে প্রার্থনা করেছে এবং আত্মসমর্পণ করেছে। ওকে তার ভালো বন্ধুকে বলে দিল, আর সে তাকে উদ্ধার করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ ذِئْبٌ إِلَى رَاعِي ‏ ‏غَنَمٍ ‏ ‏فَأَخَذَ مِنْهَا شَاةً فَطَلَبَهُ الرَّاعِي حَتَّى انْتَزَعَهَا مِنْهُ قَالَ فَصَعِدَ الذِّئْبُ عَلَى تَلٍّ ‏ ‏فَأَقْعَى ‏ ‏وَاسْتَذْفَرَ ‏ ‏فَقَالَ عَمَدْتَ إِلَى رِزْقٍ رَزَقَنِيهِ اللَّهُ عَزَّ وَجَلَّ انْتَزَعْتَهُ مِنِّي فَقَالَ الرَّجُلُ تَالَلَّهِ إِنْ رَأَيْتُ كَالْيَوْمِ ذِئْبًا يَتَكَلَّمُ قَالَ الذِّئْبُ أَعْجَبُ مِنْ هَذَا رَجُلٌ فِي ‏ ‏النَّخَلَاتِ ‏ ‏بَيْنَ ‏ ‏الْحَرَّتَيْنِ ‏ ‏يُخْبِرُكُمْ بِمَا مَضَى وَبِمَا هُوَ كَائِنٌ بَعْدَكُمْ ‏ ‏وَكَانَ الرَّجُلُ يَهُودِيًّا ‏ ‏فَجَاءَ الرَّجُلُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمَ وَخَبَّرَهُ فَصَدَّقَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا أَمَارَةٌ مِنْ أَمَارَاتٍ بَيْنَ يَدَيْ السَّاعَةِ قَدْ أَوْشَكَ الرَّجُلُ أَنْ يَخْرُجَ فَلَا يَرْجِعَ حَتَّى تُحَدِّثَهُ نَعْلَاهُ وَسَوْطُهُ مَا أَحْدَثَ أَهْلُهُ بَعْدَهُ ‏","","",""],[7719,7719,"","আমরা জানতে পেরেছি আমি কতটা ভালো আছি, ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন, যদি তিনি রাতের ডিউককে জিজ্ঞেস করেন সে সময় তিনি তাকে ঘুম থেকে বের করে দেন। একটা প্রেত দেখেছি।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ مِنْ اللَّيْلِ فَإِنَّمَا رَأَتْ مَلَكًا سَلُوا اللَّهَ مِنْ ‏ ‏فَضْلِهِ وَإِذَا سَمِعْتُمْ ‏ ‏نُهَاقَ الْحِمَارِ فَإِنَّهُ رَأَى شَيْطَانًا فَتَعَوَّذُوا بِاللَّهِ مِنْ الشَّيْطَانِ ‏","","",""],[7720,7720,"","আমরা শপথ নিয়ে কথা বলেছি, বাবার কথা শুনতে চাই, সে ঈশ্বরের কাছে যাবে আর তাকে এটা উদ্ধার করতে হবে না ঠিক আছে, গৌরব তার কাছে প্রার্থনা করতে চায় না যদি না ঈশ্বর আমার কাছে যেমন মনে হয় যে তিনি চলে যাবেন।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ يَعْنِي الْمَقْبُرِيَّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَوَضَّأُ أَحَدٌ فَيُحْسِنُ وُضُوءَهُ ‏ ‏وَيُسْبِغُهُ ‏ ‏ثُمَّ يَأْتِي الْمَسْجِدَ لَا يُرِيدُ إِلَّا الصَّلَاةَ فِيهِ إِلَّا ‏ ‏تَبَشْبَشَ اللَّهُ بِهِ كَمَا ‏ ‏يَتَبَشْبَشُ أَهْلُ الْغَائِبِ بِطَلْعَتِهِ ‏","","",""],[7721,7721,"","তিনি বলবেন, শান্তির নারীরা, আপনি কখনও তার প্রতিবেশীদের ঘৃণা করবেন না এবং আমরা কখনোই আমাদের বাবার সঙ্গে কথা বলব না । মহিলা.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ يَا نِسَاءَ الْمُسْلِمَاتِ ‏ ‏لَا ‏ ‏تَحْقِرَنَّ ‏ ‏جَارَةٌ لِجَارَتِهَا وَلَا ‏ ‏فِرْسِنَ ‏ ‏شَاةٍ ‏","","",""],[7722,7722,"","তিনি ঈশ্বরের কাছে কথা বলতে চাননি আর তাকে কেবল তার শরীরকে সমর্থন করতে ও তার হৃদয়কে হারাতেই পাওয়া গিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ أَعَزَّ جُنْدَهُ وَنَصَرَ عَبْدَهُ وَغَلَبَ الْأَحْزَابَ وَحْدَهُ وَلَا شَيْءَ بَعْدَهُ ‏","","",""],[7723,7723,"","আমি যাজকদের সাথে কথা বলেছি আমরা সুখী হতে যাচ্ছি বলে। আমার বাবা একজন পলাতক আমাদের বিক্রি করে দিয়েছেন। আগুন দিয়ে তাদের আগুন ধরিয়ে দিয়ে ঈশ্বর তা উদ্ধার করতে হবে, যদিও আমি নিয়ন্ত্রনে আছি। আমি আপনাকে আদেশ করেছি দুই ভাষা ও আগুন জ্বালিয়ে আগুন জ্বালিয়ে দেয়ার। যদি না হয়, তা হলে তাকে নির্যাতন করা হবে না। হয়ে গেছে।","‏ ‏حَدَّثَنِي ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْثٍ فَقَالَ إِنْ وَجَدْتُمْ ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏لِرَجُلَيْنِ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَأَحْرِقُوهُمَا بِالنَّارِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَرَدْنَا الْخُرُوجَ ‏ ‏إِنِّي كُنْتُ أَمَرْتُكُمْ أَنْ تُحْرِقُوا ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏بِالنَّارِ وَإِنَّ النَّارَ لَا يُعَذِّبُ بِهَا إِلَّا اللَّهُ عَزَّ وَجَلَّ فَإِنْ وَجَدْتُمُوهُمَا فَاقْتُلُوهُمَا ‏","","",""],[7724,7724,"","আমরা বাবার সাথে বাবার ভালো নাম নিয়ে কথা বলেছি, ঈশ্বর বলতে হবে মানুষ খারাপ আর মুখ আসছে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ شَرَّ النَّاسِ ذُو الْوَجْهَيْنِ يَأْتِي هَؤُلَاءِ بِوَجْهٍ وَهَؤُلَاءِ بِوَجْهٍ ‏","","",""],[7725,7725,"","আমরা কথা বলেছি, আর আমার ভয় মানে আমার সাথে আমার সাথে আমার দেখা হওয়ার স্বপ্ন, বাবার সাথে আমার ছেলের সদয়তার কথা তিনি শুনেছেন যে তিনি জিজ্ঞেস করবেন তিনি আমাকে জিজ্ঞাসা করবেন ঈশ্বর, তিনি সমাজের মধ্যে আপনাকে আশীর্বাদ করতে চেয়েছিলেন এই বলে যে, আপনি সবচেয়ে ভালো মানুষ হবেন এই বিশ্বাস করার জন্য যে আপনি সবচেয়ে ভালো ব্যক্তি হবেন, তা বিশ্বাস করার জন্য যে আপনি হবেন সেই ব্যক্তি হতে পারে যে, সে হতে পারে সেই ব্যক্তি যে হতে পারে । ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏والْخُزَاعِيُّ يَعْنِي أَبَا سَلَمَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي سَالِمٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ مُعْتِبٍ الْهُذَلِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاذَا رَدَّ إِلَيْكَ رَبُّكَ فِي الشَّفَاعَةِ فَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَقَدْ ظَنَنْتُ أَنَّكَ أَوَّلُ مَنْ يَسْأَلُنِي عَنْ ذَلِكَ مِنْ أُمَّتِي لِمَا رَأَيْتُ مِنْ حِرْصِكَ عَلَى الْعِلْمِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏مَا يَهُمُّنِي مِنْ ‏ ‏انْقِصَافِهِمْ ‏ ‏عَلَى أَبْوَابِ الْجَنَّةِ أَهَمُّ عِنْدِي مِنْ تَمَامِ شَفَاعَتِي وَشَفَاعَتِي لِمَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصًا يُصَدِّقُ قَلْبُهُ لِسَانَهُ وَلِسَانُهُ قَلْبَهُ ‏","","",""],[7726,7726,"","আমি আমার বাবার সঙ্গে আমার বাবার সম্পর্কে দুটো গোপন কথা বলেছিলাম । তারা এমন কিছু বলত, যা আমাদের হারিয়ে ফেলত । আমি একটা শপথ করে বলেছিলাম যে, সে একটা স্ট্রোক করেছে, সে একটা গাছের ওপর মারা গেছে, সে বলেছিল, সে নাকি মারা গেছে । তারপর সে মেঘে গিয়ে তাকে বলে গেল, \" যুবক ছেলে\" সে তাকে বলে দিয়েছে যে আমার ছেলে তোমাকে খুশি করেছে। গলা একটা ছেলে সে তার সাথে নিয়ে গেছে আর পরের লড়াই সে করে অন্যটা বলেছে। তারা বলেছে, তারা আমাকে আর করতে পারবে না, আর তারপর সে চলে যাবে। তার মুখ দিয়ে তাকে ঢুকিয়ে তার সাথে ফিট করে দিতে হবে। যেমন তার মা তাকে বুকে চুমু দিয়ে মাকে চুমু দিয়ে দিল যখন সে এই ব্যাজটা করেছিল। তুমি বলেছিলে, অন্যেরা আমাকে তার মতো করে বলতে, মা, যাত্রীরা ছিল সবার মূল। ভালো, সে জিতবে না, চুরি করতে পারবে না, সে আমার হৃদয় চুরি করেনি, আর সে বলেছে ঈশ্বর একজন ভাল মানুষ। আমার বাবা তাকে ভবিষ্যদ্বাণী করার জন্য আদেশ দিয়েছেন এবং সে ইচ্ছা পূরণ করবে না। আমার ছেলে গুরুতরভাবে আহত হয়ে এবং তার কাছে যে - কথা বলা হয়েছিল, সেই জনের নাম ছিল একজন অপরাধী অথবা একজন অপরাধী । একজন মানুষ ছিলেন সেই পুরুষ যিনি একজন মানুষ ছিলেন পুরুষ যিনি একজন মানুষ ছিলেন ছিলেন পুরুষ মানুষ । যে পুরুষ পুরুষ মানুষ ছিলেন সে পুরুষ মানুষ যে ছিল সে ছিল পুরুষ মানুষ মানুষ যে ছিল সে ছিল পুরুষ মানুষ মানুষ যে ছিল সে ছিল পুরুষ মানুষ মানুষ মানুষ । সে ছিল সে ছিল মানুষ যে ছিল পুরুষ মানুষ , সে ছিল মানুষ মানুষ । যে পুরুষ পুরুষ মানুষ ছিল সে ছিল পুরুষ মানুষ মানুষ মানুষ , সে ছিল সে মানুষ মানুষ , যে ছিল সে ছিল মানুষ মানুষ , যে ছিল সে ছিল মানুষ মানুষ । যে লোক পুরুষ ছিল সে ছিল পরিচিত একজন মানুষ , সে ছিল একজন মানুষ বৈ তো নয় । এমন একজন মানুষ ছিলেন যে একজন পুরুষ যিনি একজন পুরুষ ছিলেন যে কিনা একজন মানুষ যে কিনা তার মায়ের সাথে ছিলেন। তিনি সবসময় প্রার্থনা করতেন যে, আমি তার মাকে বেছে নিতাম, “যাকে বলে” সে তাকে তোমার মত বলতে ফোন করল, তারপর তাকে মেরে ফেলতে বলেছিল... ...যেন তুমি মুখে ধরা পড়ে তাকে মেরে ফেলে, তাই তার কথা শুনে তার কথা শুনে শুনে শুনে সে আমার ছেলের একজন জেনিক ছিল।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ سِيرِينَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَتَكَلَّمْ فِي الْمَهْدِ إِلَّا ثَلَاثَةٌ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏وَكَانَ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏عَابِدٌ يُقَالُ لَهُ ‏ ‏جُرَيْجٌ ‏ ‏فَابْتَنَى ‏ ‏صَوْمَعَةً ‏ ‏وَتَعَبَّدَ فِيهَا قَالَ فَذَكَرَ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏يَوْمًا عِبَادَةَ ‏ ‏جُرَيْجٍ ‏ ‏فَقَالَتْ ‏ ‏بَغِيٌّ ‏ ‏مِنْهُمْ لَئِنْ شِئْتُمْ لَأُصْبِيَنَّهُ فَقَالُوا قَدْ شِئْنَا قَالَ فَأَتَتْهُ فَتَعَرَّضَتْ لَهُ فَلَمْ يَلْتَفِتْ إِلَيْهَا فَأَمْكَنَتْ نَفْسَهَا مِنْ رَاعٍ كَانَ يَأْوِي غَنَمَهُ إِلَى أَصْلِ ‏ ‏صَوْمَعَةِ ‏ ‏جُرَيْجٍ ‏ ‏فَحَمَلَتْ فَوَلَدَتْ غُلَامًا فَقَالُوا مِمَّنْ قَالَتْ مِنْ ‏ ‏جُرَيْجٍ ‏ ‏فَأَتَوْهُ فَاسْتَنْزَلُوهُ فَشَتَمُوهُ وَضَرَبُوهُ وَهَدَمُوا ‏ ‏صَوْمَعَتَهُ ‏ ‏فَقَالَ مَا شَأْنُكُمْ قَالُوا إِنَّكَ زَنَيْتَ بِهَذِهِ ‏ ‏الْبَغِيِّ ‏ ‏فَوَلَدَتْ غُلَامًا قَالَ وَأَيْنَ هُوَ قَالُوا هَا هُوَ ذَا قَالَ فَقَامَ فَصَلَّى وَدَعَا ثُمَّ انْصَرَفَ إِلَى الْغُلَامِ فَطَعَنَهُ بِإِصْبَعِهِ وَقَالَ بِاللَّهِ يَا غُلَامُ مَنْ أَبُوكَ قَالَ أَنَا ابْنُ الرَّاعِي ‏ ‏فَوَثَبُوا ‏ ‏إِلَى ‏ ‏جُرَيْجٍ ‏ ‏فَجَعَلُوا يُقَبِّلُونَهُ وَقَالُوا نَبْنِي ‏ ‏صَوْمَعَتَكَ ‏ ‏مِنْ ذَهَبٍ قَالَ لَا حَاجَةَ لِي فِي ذَلِكَ ابْنُوهَا مِنْ طِينٍ كَمَا كَانَتْ قَالَ وَبَيْنَمَا امْرَأَةٌ فِي حِجْرِهَا ابْنٌ لَهَا تُرْضِعُهُ إِذْ مَرَّ بِهَا رَاكِبٌ ‏ ‏ذُو شَارَةٍ ‏ ‏فَقَالَتْ اللَّهُمَّ اجْعَلْ ابْنِي مِثْلَ هَذَا قَالَ فَتَرَكَ ثَدْيَهَا وَأَقْبَلَ عَلَى الرَّاكِبِ فَقَالَ اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ قَالَ ثُمَّ عَادَ إِلَى ثَدْيِهَا يَمُصُّهُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْكِي عَلَيَّ صَنِيعَ الصَّبِيِّ وَوَضْعَهُ إِصْبَعَهُ فِي فَمِهِ فَجَعَلَ يَمُصُّهَا ثُمَّ مُرَّ بِأَمَةٍ تُضْرَبُ فَقَالَتْ اللَّهُمَّ لَا تَجْعَلْ ابْنِي مِثْلَهَا قَالَ فَتَرَكَ ثَدْيَهَا وَأَقْبَلَ عَلَى أُمِّهِ فَقَالَ اللَّهُمَّ اجْعَلْنِي مِثْلَهَا قَالَ فَذَلِكَ حِينَ تَرَاجَعَا ‏ ‏الْحَدِيثَ فَقَالَتْ حَلْقَى مَرَّ الرَّاكِبُ ‏ ‏ذُو الشَّارَةِ ‏ ‏فَقُلْتُ اللَّهُمَّ اجْعَلْ ابْنِي مِثْلَهُ فَقُلْتَ اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ وَمُرَّ بِهَذِهِ الْأَمَةِ فَقُلْتُ اللَّهُمَّ لَا تَجْعَلْ ابْنِي مِثْلَهَا فَقُلْتَ اللَّهُمَّ اجْعَلْنِي مِثْلَهَا فَقَالَ يَا ‏ ‏أُمَّتَاهْ إِنَّ الرَّاكِبَ ‏ ‏ذُو الشَّارَةِ ‏ ‏جَبَّارٌ مِنْ الْجَبَابِرَةِ وَإِنَّ هَذِهِ الْأَمَةَ يَقُولُونَ زَنَتْ وَلَمْ تَزْنِ وَسَرَقَتْ وَلَمْ تَسْرِقْ وَهِيَ تَقُولُ ‏ ‏حَسْبِيَ اللَّهُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمْ يَتَكَلَّمْ فِي الْمَهْدِ إِلَّا ثَلَاثَةٌ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَصَبِيٌّ كَانَ فِي زَمَانِ ‏ ‏جُرَيْجٍ ‏ ‏وَصَبِيٌّ آخَرُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ وَأَمَّا ‏ ‏جُرَيْجٌ ‏ ‏فَكَانَ رَجُلًا عَابِدًا فِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَكَانَتْ لَهُ أُمٌّ وَكَانَ يَوْمًا ‏ ‏يُصَلِّي إِذْ اشْتَاقَتْ إِلَيْهِ أُمُّهُ فَقَالَتْ يَا ‏ ‏جُرَيْجُ ‏ ‏فَقَالَ يَا رَبِّ الصَّلَاةُ خَيْرٌ أَمْ أُمِّي آتِيهَا ثُمَّ صَلَّى وَدَعَتْهُ فَقَالَ مِثْلَ ذَلِكَ ثُمَّ دَعَتْهُ فَقَالَ مِثْلَ ذَلِكَ وَصَلَّى فَاشْتَدَّ عَلَى أُمِّهِ وَقَالَتْ اللَّهُمَّ أَرِ ‏ ‏جُرَيْجًا ‏ ‏الْمُومِسَاتِ ‏ ‏ثُمَّ صَعِدَ ‏ ‏صَوْمَعَةً ‏ ‏لَهُ وَكَانَتْ زَانِيَةٌ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[7727,7727,"","আমি আমার মায়ের স্বপ্ন শুনেছি বাবা হারাহরের কথা শুনে যে ঈশ্বর এটা দিয়েছেন আর আছে ঈশ্বরকে দেওয়া হয়েছে, আমি দেখতে চাই তারা কিভাবে প্রভুর পথে যাবে... আর তাদের মনের কথা যেন বাবার মত।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَفْلَحُ بْنُ سَعِيدٍ ‏ ‏شَيْخٌ مِنْ أَهْلِ ‏ ‏قُبَاءٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَافِعٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنْ طَالَ بِكَ مُدَّةٌ أَوْشَكْتَ أَنْ ‏ ‏تَرَى قَوْمًا يَغْدُونَ فِي سَخَطِ اللَّهِ وَيَرُوحُونَ فِي لَعْنَتِهِ فِي أَيْدِيهِمْ مِثْلُ أَذْنَابِ الْبَقَرِ ‏","","",""],[7728,7728,"","আমরা আমার আত্মার মহিমার সাথে কথা বলেছি, আমরা একটা পার্থক্য করার চেষ্টা করেছি, সে তার জন্য প্রার্থনা করেছে এবং আমি তোমার জন্য ভয় পাচ্ছি কিন্তু আমি তোমার জ্ঞানের জন্য ভয় পাচ্ছি। কিন্তু আমি ভয় পাচ্ছি তুমি সেবা করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ الْبُرْسَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ يَعْنِي ابْنَ بُرْقَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَخْشَى عَلَيْكُمْ الْفَقْرَ وَلَكِنْ أَخْشَى عَلَيْكُمْ التَّكَاثُرَ وَمَا أَخْشَى عَلَيْكُمْ الْخَطَأَ وَلَكِنْ أَخْشَى عَلَيْكُمْ الْعَمْدَ ‏","","",""],[7729,7729,"","আমরা এত উদার হওয়ার চেষ্টা করেছি যে আমার দৃষ্টির ভালোবাসা নিয়ে কথা বলেছি, আমার বাবা একজন পলাতক। ভগবানের হত্যা করা থেকে, তাকে হত্যা করার চেয়ে বরং আমাকে মেরে ফেলতে হবে, আল্লাহ আমাকে পরিকল্পনা করতে বাধ্য করেছেন, তিনি বললেন, তিনি বললেন, তিনি হয়ত মারা যেতে পারেন। এই কথা হচ্ছে, প্রভু, আমি দেখেছি যে আমি ঈশ্বরের পথে মারা গিয়েছি, নিশ্চয়ই ঈশ্বরের ছায়াতে ধরা পড়ে আছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ الْأَنْصَارِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عِيَاضُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَرْحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ النَّاسَ فَذَكَرَ الْإِيمَانَ بِاللَّهِ وَالْجِهَادَ فِي سَبِيلِ اللَّهِ مِنْ أَفْضَلِ الْأَعْمَالِ عِنْدَ اللَّهِ قَالَ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ وَأَنَا صَابِرٌ مُحْتَسِبٌ مُقْبِلًا غَيْرَ مُدْبِرٍ كَفَّرَ اللَّهُ عَنِّي خَطَايَايَ قَالَ نَعَمْ قَالَ فَكَيْفَ قُلْتَ قَالَ فَرَدَّ عَلَيْهِ الْقَوْلَ كَمَا قَالَ قَالَ نَعَمْ قَالَ فَكَيْفَ قُلْتَ قَالَ فَرَدَّ عَلَيْهِ الْقَوْلَ أَيْضًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ صَابِرًا مُحْتَسِبًا مُقْبِلًا غَيْرَ مُدْبِرٍ كَفَّرَ اللَّهُ عَنِّي خَطَايَايَ قَالَ نَعَمْ إِلَّا الدَّيْنَ فَإِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏سَارَّنِي بِذَلِكَ ‏","","",""],[7730,7730,"","আমরা আমার বাবাকে কুত্তা বলার সবচেয়ে ভালো সময় নিয়ে কথা বলেছি, ঈশ্বর তাকে শিক্ষা দিয়েছেন আর আমরা প্রার্থনায় নিরাপদ থাকবো, সে আমাদের উড়িয়ে দিতে ভয় পাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّنَا فِي الصَّلَاةِ فَيَجْهَرُ وَيُخَافِتُ فَجَهَرْنَا فِيمَا جَهَرَ فِيهِ وَخَافَتْنَا فِيمَا خَافَتَ فِيهِ فَسَمِعْتُهُ يَقُولُ ‏ ‏لَا صَلَاةَ إِلَّا بِقِرَاءَةٍ ‏","","",""],[7731,7731,"","আমরা সবার সেরা লোকদের কথা বলেছি আমার ভাই, আমার ভাই, ঈশ্বরের কাছে প্রার্থনা করবে আর আমি তোমাকে সমৃদ্ধ করব না আর শপথ করে শপথ নিতে চাই","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[7732,7732,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং এমন কারও প্রার্থনা গ্রহণ করবেন না, যিনি এই কথা বলার জন্য বলেন যে, তার একজন ব্যক্তি আছেন, যিনি এই কথা বলার জন্য তার সঙ্গে কথা বলেছেন । আমি, একটা কিট খারাপ নাকি খারাপ কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْبَلُ صَلَاةُ مَنْ أَحْدَثَ حَتَّى يَتَوَضَّأَ قَالَ فَقَالَ لَهُ رَجُلٌ مِنْ أَهْلِ ‏ ‏حَضْرَمَوْتَ ‏ ‏مَا الْحَدَثُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ فُسَاءٌ أَوْ ضُرَاطٌ ‏","","",""],[7733,7733,"","আমার বাবার অনুসন্ধানের ব্যাপারে আমার বাবার সব থেকে ভালো কথা বলা হয়েছিল। তার মাথা নষ্ট হয়ে গেলে তারা শুধু তা করে, নয়তো তারা তাকে ধীর করে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَرَفَ صَوْتَهُ فَقَالَ ‏ ‏ادْخُلْ فَقَالَ إِنَّ فِي الْبَيْتِ سِتْرًا فِي الْحَائِطِ فِيهِ تَمَاثِيلُ فَاقْطَعُوا رُءُوسَهَا فَاجْعَلُوهَا بِسَاطًا أَوْ وَسَائِدَ فَأَوْطَئُوهُ فَإِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ تَمَاثِيلُ ‏","","",""],[7734,7734,"","তারা তাদের আত্মার দ্বারা সিংহাসনে বসেছিলেন এবং তাদের আহ্বান জানিয়েছিলেন ও তাদের কাছে প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَا ‏ ‏الْحَبَشَةُ ‏ ‏يَلْعَبُونَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحِرَابِهِمْ ‏ ‏دَخَلَ ‏ ‏عُمَرُ ‏ ‏فَأَهْوَى ‏ ‏إِلَى ‏ ‏الْحَصْبَاءِ ‏ ‏يَحْصِبُهُمْ ‏ ‏بِهَا فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُمْ يَا ‏ ‏عُمَرُ ‏","","",""],[7735,7735,"","আমরা যতগুলো দলের সাথে দেখা করেছি, যারা আমাদের চেয়ে ভালো তাদের কথা বলছি, তাদের জন্য আমার ঈশ্বরের শোকের কথা তিনি প্রার্থনা করতে বলেছিলেন, যদি তার রক্ত থেকে চলে যায় তাহলে সে ধনীদের রক্ত দূরে যেতে বাধ্য হবে। সে এটা নিয়ন্ত্রণ করছে.","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ الدِّينُ عِنْدَ ‏ ‏الثُّرَيَّا ‏ ‏لَذَهَبَ رَجُلٌ مِنْ ‏ ‏فَارِسَ ‏ ‏أَوْ أَبْنَاءِ ‏ ‏فَارِسَ ‏ ‏حَتَّى يَتَنَاوَلَهُ ‏","","",""],[7736,7736,"","আমরা সেই জনতার সম্বন্ধে আমাদের সম্বন্ধে সবচেয়ে ভাল কথা বলেছিলাম, যারা আমাদের প্রভু সম্বন্ধে আমাদের কথা বলেছে । ঈশ্বর তাদের ক্ষমা করে দেন.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْ لَمْ تُذْنِبُوا لَذَهَبَ اللَّهُ بِكُمْ وَلَجَاءَ بِقَوْمٍ يُذْنِبُونَ فَيَسْتَغْفِرُونَ اللَّهَ فَيَغْفِرُ لَهُمْ ‏","","",""],[7737,7737,"","আমরা জনতার কথা বলেছিলাম, আমাদের স্বপ্নের কথা বলতে হবে। একটা উপহার বললো, ঈশ্বরের প্রার্থনা করতে হবে, প্রভুকে উদ্ধার করতে হবে। তার কাজে লর্ডকে আত্মসমর্পণ করা হবে না। মরুভূমি আর আদেশ হল একটা বোকা হওয়া, আমি সময়ের প্রলোভনের সাথে কথা বলতে চাই...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏لَا يَصْبُغُونَ فَخَالِفُوهُمْ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فِي حَدِيثِهِ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَالْأَمْرُ بِالْأَصْبَاغِ فَأَحْلَكُهَا أَحَبُّ إِلَيْنَا ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَكَانَ ‏ ‏الزُّهْرِيُّ ‏ ‏يَخْضِبُ ‏ ‏بِالسَّوَادِ ‏","","",""],[7738,7738,"","আমি আমার বাবা আমাদের কাছে তার বন্য স্বপ্ন সম্পর্কে কত কথা বলেছেন, আমি জানি এটা তার কাছে প্রার্থনা করা সম্পর্কে না আর তিনি বলবেন যে তিনি পানিকে থামাতে পারবেন না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُمْنَعُ ‏ ‏فَضْلُ ‏ ‏الْمَاءِ لِيُمْنَعَ بِهِ فَضْلُ ‏ ‏الْكَلَإِ ‏","","",""],[7739,7739,"","আমরা আমার বাবাকে কতটুকু বলেছি, আমার ভালবাসা থেকে দূরে সরে যেতে, ঈশ্বরের দয়ায় এটা আছে আর সে যে শহরের কিছু শহরে আত্মসমর্পণ করেছে, সে বলেছে যে সে নয় একজন ভালো বাবা, তিনি বলেছেন এটা ঠিক এই রকম আর এটা তিন বার তিনি তার অধিকার রক্ষা করার চেষ্টা করেছেন এবং তিনি তার হাত আছে তিনি আপনি একটি ছাগল হতে বলা হয় না. আমি যা বলেছি সব ধন-সম্পদ আমি বলেছি, ঈশ্বর বলে, এটা এক ঘন্টা আগে, তুমি কি বলেছিলে, বাবা, তুমি কি জানো মানুষ না, আমি তাকে জিজ্ঞাসা করি সে ঠিক আছে, মানুষ তাকে যেতে দিবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏كُمَيْلِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَخْلٍ لِبَعْضِ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَلَكَ الْمُكْثِرُونَ إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا ثَلَاثَ مَرَّاتٍ حَثَا بِكَفِّهِ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ وَبَيْنَ يَدَيْهِ وَقَلِيلٌ مَا هُمْ ثُمَّ مَشَى سَاعَةً فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ فَقُلْتُ بَلَى يَا رَسُولَ اللَّهِ قَالَ قُلْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ وَلَا مَلْجَأَ مِنْ اللَّهِ إِلَّا إِلَيْهِ ثُمَّ مَشَى سَاعَةً فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَلْ تَدْرِي مَا حَقُّ النَّاسِ عَلَى اللَّهِ وَمَا حَقُّ اللَّهِ عَلَى النَّاسِ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَإِنَّ حَقَّ اللَّهِ عَلَى النَّاسِ أَنْ يَعْبُدُوهُ وَلَا يُشْرِكُوا بِهِ شَيْئًا فَإِذَا فَعَلُوا ذَلِكَ فَحَقٌّ عَلَيْهِ أَنْ لَا يُعَذِّبَهُمْ ‏","","",""],[7740,7740,"","আমরা আমার ভাই, হয়তো খোদা সম্পর্কে আমাদের কথা বলেছি, সে বলল ঈশ্বর তার জন্য প্রার্থনা করুক আর সে সাহায্য করতে পারবে না, সে ক্লান্ত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّ أَحَدُكُمْ الْمَوْتَ إِمَّا مُحْسِنٌ فَيَزْدَادَ إِحْسَانًا وَإِمَّا مُسِيءٌ فَلَعَلَّهُ أَنْ يَسْتَعْتِبَ ‏","","",""],[7741,7741,"","আমরা আমাদের বিদায়ের সেরাটা নিয়ে কথা বলেছি, ঈশ্বরের প্রার্থনা হবে তার কাছে আর তার জামার কাছে সমর্পণ করা হবে যে কিনা তার জামার উপর মারা গেছে আর ভদ্র ভাবে বলে যে তার কোন সম্পর্ক নেই। ওকে বলো আমি তোমাকে কিছু বিশ্বাস করতে বলছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ فَقَالَ فِي حَلِفِهِ وَاللَّاتِ فَلْيَقُلْ لَا إِلَهَ إِلَّا اللَّهُ وَمَنْ قَالَ لِصَاحِبِهِ تَعَالَ أُقَامِرْكَ فَلْيَتَصَدَّقْ بِشَيْءٍ ‏","","",""],[7742,7742,"","ঈশ্বর এমন একজন ব্যক্তিকে গ্রহণ করেছেন, যিনি কখনো এমনটা বলতে চাননি যে, ঈশ্বর কখনো তার সঙ্গে থাকেননি । খুন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ فَقَالَ إِنْ شَاءَ اللَّهُ لَمْ ‏ ‏يَحْنَثْ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَهُوَ اخْتَصَرَهُ ‏ ‏يَعْنِي ‏ ‏مَعْمَرًا ‏","","",""],[7743,7743,"","আমরা ঈশ্বরের সর্বোচ্চ কথা বলেছি, কিন্তু ঈশ্বর আমাকে বলেছেন যে খোদা হয়ত পারেন। ইমাম বললেন আমি আমার বাবার স্ত্রীকে দেখতে পাচ্ছি। ঈশ্বরের উপর ভরসা রাখো, আমি হলাম ঈশ্বরের কাছে, কিভাবে লবণ পানিতে যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يُحَنِّسَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْقَرَّاظِ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَشْهَدُ الثَّلَاثَ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏مَنْ أَرَادَ أَهْلَ الْبَلْدَةِ بِسُوءٍ ‏ ‏يَعْنِي أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏أَذَابَهُ اللَّهُ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ ‏","","",""],[7744,7744,"","আমরা বাবার সবচেয়ে ভালোটা নিয়ে কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি বলব যে আমি এমন একজন মানুষের কাছে যেতে চাই যে তার পরে যেতে চায়। তার মানে এই নয় যে, ঈশ্বর তাকে মেরে ফেলেছেন এবং তাকে গুলি করেছে। ঈশ্বরের কাছে নিজেকে সমর্পণ করতে হবে, আমি ঈশ্বরের নামে শপথ করছি যে আমি প্রভু ও ঈশ্বর নই। আল্লাহ্‌, যিনি শান্তি জয় করেছেন এবং অবশ্যই নেতা হবেন। আমি আমার ছেলেকে বলেছিলাম যে, বাবা একজন পরাজিত লোক... ...যে আমাকে দেখে নিল যে আমার কাছে যায়নি। সে তার নিজের কারো কাছে আত্মসমর্পণ করেছে, তার কথা শোনা উচিত। সে দুটো অপরাধীর একজন মানুষকে হারিয়েছে। কিন্তু ঈশ্বর আপনার এই অনুষ্ঠানকে মেনে নিয়েছেন এবং মুক্ত হয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شَهِدْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَقَالَ ‏ ‏يَعْنِي لِرَجُلٍ يَدَّعِي الْإِسْلَامَ هَذَا مِنْ أَهْلِ النَّارِ فَلَمَّا حَضَرْنَا الْقِتَالَ قَاتَلَ الرَّجُلُ قِتَالًا شَدِيدًا فَأَصَابَتْهُ جِرَاحَةٌ فَقِيلَ يَا رَسُولَ اللَّهِ ‏ ‏الرَّجُلُ ‏ ‏الَّذِي قُلْتَ لَهُ إِنَّهُ مِنْ أَهْلِ النَّارِ فَإِنَّهُ قَاتَلَ الْيَوْمَ قِتَالًا شَدِيدًا وَقَدْ مَاتَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى النَّارِ فَكَادَ بَعْضُ النَّاسِ أَنْ ‏ ‏يَرْتَابَ ‏ ‏فَبَيْنَمَا هُمْ عَلَى ذَلِكَ إِذْ قِيلَ فَإِنَّهُ لَمْ يَمُتْ وَلَكِنْ بِهِ جِرَاحٌ شَدِيدٌ فَلَمَّا كَانَ مِنْ اللَّيْلِ لَمْ يَصْبِرْ عَلَى الْجِرَاحِ فَقَتَلَ نَفْسَهُ فَأُخْبِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ فَقَالَ اللَّهُ أَكْبَرُ أَشْهَدُ أَنِّي عَبْدُ اللَّهِ وَرَسُولُهُ ثُمَّ أَمَرَ ‏ ‏بِلَالًا ‏ ‏فَنَادَى فِي النَّاسِ أَنَّهُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ إِلَّا نَفْسٌ مُسْلِمَةٌ وَأَنَّ اللَّهَ عَزَّ وَجَلَّ يُؤَيِّدُ هَذَا الدِّينَ بِالرَّجُلِ الْفَاجِرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شَهِدْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِرَجُلٍ مِمَّنْ مَعَهُ ‏ ‏يُذْعِنُ ‏ ‏بِالْإِسْلَامِ إِنَّ هَذَا مِنْ أَهْلِ النَّارِ فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَاشْتَدَّ عَلَى رِجَالٍ مِنْ الْمُسْلِمِينَ فَقَالُوا يَا رَسُولَ اللَّهِ قَدْ صَدَّقَ اللَّهُ حَدِيثَكَ وَقَدْ انْتَحَرَ فُلَانٌ فَقَتَلَ نَفْسَهُ ‏","","",""],[7745,7745,"","আমরা বাবার সবচেয়ে ভাল কথা বলেছি... ...আমার বাবার কাছে প্রার্থনা করে... ...ঈশ্বর তার কাছে প্রার্থনা করেছিলেন... ...এবং তুমি যা প্রতিজ্ঞা করেছিলে তা মেনে নিতে, যিনি প্রভুর পথে নিহত হয়েছেন, তিনি বলেছিলেন হত্যা করা হবে। প্রভুর অনুগ্রহ এবং বাধ্যবাধকতার উপর হত্যা করা বাধ্যতামূলক।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَعُدُّونَ الشَّهِيدَ فِيكُمْ قَالُوا مَنْ قُتِلَ فِي سَبِيلِ اللَّهِ قَالَ ‏ ‏إِنَّ شُهَدَاءَ أُمَّتِي إِذًا لَقَلِيلٌ الْقَتْلُ فِي سَبِيلِ اللَّهِ شَهَادَةٌ ‏ ‏وَالْبَطَنُ ‏ ‏شَهَادَةٌ ‏ ‏وَالْغَرَقُ ‏ ‏شَهَادَةٌ ‏ ‏وَالنُّفَسَاءُ ‏ ‏شَهَادَةٌ وَالطَّاعُونُ شَهَادَةٌ ‏","","",""],[7746,7746,"","আমরা বলেছিলাম যে, কীভাবে আমার বাবা কৌশলতা দেখাতে পছন্দ করবে । আমি তোমার মত যাব যদি ঈশ্বর কিছু করে থাকেন, তাহলে তুমি যা বলবে, সে প্রভুর সাধু, ঠিক আছে। তিনটা খারাপ মেয়ের সাথে লাইন করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ اصْطَفَى مِنْ الْكَلَامِ أَرْبَعًا سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ قَالَ وَمَنْ قَالَ سُبْحَانَ اللَّهِ كُتِبَتْ لَهُ بِهَا عِشْرُونَ حَسَنَةً وَحُطَّ عَنْهُ عِشْرُونَ سَيِّئَةً وَمَنْ قَالَ اللَّهُ أَكْبَرُ فَمِثْلُ ذَلِكَ وَمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَمِثْلُ ذَلِكَ وَمَنْ قَالَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ مِنْ قِبَلِ نَفْسِهِ كُتِبَ لَهُ بِهَا ثَلَاثُونَ حَسَنَةً وَحُطَّ عَنْهُ بِهَا ثَلَاثُونَ سَيِّئَةً ‏","","",""],[7747,7747,"","আমরা আমার ভাইয়ের অনুগ্রহ নষ্ট করার ব্যাপারে কথা বলেছিলাম, ঈশ্বর শেষ বারের মতো উদ্ধার করতে চান।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي آخِرِ الزَّمَانِ يَظْهَرُ ‏ ‏ذُو السُّوَيْقَتَيْنِ ‏ ‏عَلَى ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ حَسِبْتُ أَنَّهُ قَالَ فَيَهْدِمُهَا ‏","","",""],[7748,7748,"","আমি আমার জীবনের সর্বোত্তমটা সম্বন্ধে বলেছিলাম । তারা এর ভিতরে আছে আর তারপর সে বলেছে নাবিকরা মানুষ খেলতে পারবে, আর আমি তোমার প্রতিবেশীকে নিরাপদ রাখতে পারবো। আর আমি তোমার মুখ ভেঙ্গে দিতে পছন্দ করি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي طَارِقٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَأْخُذُ مِنْ أُمَّتِي خَمْسَ خِصَالٍ فَيَعْمَلُ بِهِنَّ أَوْ يُعَلِّمُهُنَّ مَنْ يَعْمَلُ بِهِنَّ قَالَ قُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ فَأَخَذَ بِيَدِي فَعَدَّهُنَّ فِيهَا ثُمَّ قَالَ اتَّقِ الْمَحَارِمَ تَكُنْ أَعْبَدَ النَّاسِ وَارْضَ بِمَا قَسَمَ اللَّهُ لَكَ تَكُنْ أَغْنَى النَّاسِ وَأَحْسِنْ إِلَى جَارِكَ تَكُنْ مُؤْمِنًا وَأَحِبَّ لِلنَّاسِ مَا تُحِبُّ لِنَفْسِكَ تَكُنْ مُسْلِمًا وَلَا تُكْثِرْ الضَّحِكَ فَإِنَّ كَثْرَةَ الضَّحِكِ تُمِيتُ الْقَلْبَ ‏","","",""],[7749,7749,"","আমরা আমাদের জীবনের সেরাটা, ভাই, ভাই, সে ঈশ্বরের সেবায় গিয়েছে, সে একটি ভাল বছরের গোপন আছে এবং তার একটি ভাল বছর আছে. তারা একশ বৃদ্ধ লোকের কাছে তাদের অনুসরণ করে, যারা একটি মোটেল থেকে নামছে । পাশ দিয়ে চলে গেলে, তারা বলে যে তারা রাজধানীর নাম না। একজন মৃত ব্যক্তি শুধু বলতে পেরেছে যে, তিনি আমাদের কাছে কত টাকা প্রতিজ্ঞা করেছেন। যদি শুধু একজন মারা যান, তাহলে তারা তাদের একজনই হবে। আমরা পৃথিবীর অন্ধকারে নেমে যাবো, তাদেরকে বলে দেব যে আমরা আমার গুরুত্বের সাথে কাটাবো, কিন্তু আমরা আমার পাপের মূল্য খরচ করি, কিন্তু তারা দুজন জিতবে বা তাদের যাজক পালিয়ে যাবে। আমি তাদের অনুসরণ করব যদি তারা তিমির সাথে লুকিয়ে থাকে, আর এটা ছিল মৃত্যু। সে তার প্রতারণার জন্য অন্ধ হয়ে গেছে, তার মাথায় এটা গেঁথেছে। সে যখন তাকে দেখে, তখন সে তাকে মেরে ফেলবে, সে বলছিল আমি যা দেখেছি তা ভালো ছিল, সে তার মুখ থেকে এটা খায়। একমাত্র সে। কে তার কাছে আটকে ছিল এটা বলতে যে তারা আগুন থেকে কেড়ে নিয়েছে তুমি আগে যেতে এবং বলবে তুমি হয়তো তোমার গর্ভ থেকে সরিয়ে নিয়ে যেতে পারে। আমি মনে করি তারা আমার আসল পরিচয়ের জন্য ফিরে এসেছে। আমি যা করছি তা হলো, আমি আসলে জানি। হত্যা আমার সাহস আছে, তোমার মনে মনে আছে আমি ভয় পাচ্ছি, আর তার মৃত্যুর পর তার নাম খারাপ হয়ে গেছে। আর সে তার মহান লোকদের খুন করতে বিরাট ক্ষতি করেছে, সে মারা যাচ্ছে, তারা এর থেকে বড় কিছু পাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي سُفْيَانَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏عَيْنًا ‏ ‏وَأَمَّرَ عَلَيْهِمْ ‏ ‏عَاصِمَ بْنَ ثَابِتٍ ‏ ‏وَهُوَ جَدُّ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏فَانْطَلَقُوا حَتَّى إِذَا كَانُوا بِبَعْضِ الطَّرِيقِ بَيْنَ ‏ ‏عُسْفَانَ ‏ ‏وَمَكَّةَ ‏ ‏نُزُولًا ذُكِرُوا لِحَيٍّ مِنْ ‏ ‏هُذَيْلٍ ‏ ‏يُقَالُ لَهُمْ ‏ ‏بَنُو لِحْيَانَ ‏ ‏فَتَبِعُوهُمْ بِقَرِيبٍ مِنْ مِائَةِ رَجُلٍ ‏ ‏رَامٍ ‏ ‏فَاقْتَصُّوا ‏ ‏آثَارَهُمْ حَتَّى نَزَلُوا مَنْزِلًا نَزَلُوهُ فَوَجَدُوا فِيهِ نَوَى تَمْرٍ تَزَوَّدُوهُ مِنْ تَمْرِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالُوا هَذَا مِنْ تَمْرِ ‏ ‏يَثْرِبَ ‏ ‏فَاتَّبَعُوا آثَارَهُمْ حَتَّى لَحِقُوهُمْ فَلَمَّا أَحَسَّهُمْ ‏ ‏عَاصِمُ بْنُ ثَابِتٍ ‏ ‏وَأَصْحَابُهُ لَجَئُوا إِلَى ‏ ‏فَدْفَدٍ ‏ ‏وَقَدْ جَاءَ الْقَوْمُ فَأَحَاطُوا بِهِمْ وَقَالُوا لَكُمْ الْعَهْدُ وَالْمِيثَاقُ إِنْ نَزَلْتُمْ إِلَيْنَا أَنْ لَا نَقْتُلَ مِنْكُمْ أَحَدًا فَقَالَ ‏ ‏عَاصِمُ بْنُ ثَابِتٍ ‏ ‏أَمَّا أَنَا فَلَا أَنْزِلُ فِي ذِمَّةِ كَافِرٍ اللَّهُمَّ أَخْبِرْ عَنَّا رَسُولَكَ قَالَ فَقَاتَلُوهُمْ فَرَمَوْهُمْ فَقَتَلُوا ‏ ‏عَاصِمًا ‏ ‏فِي سَبْعَةِ ‏ ‏نَفَرٍ ‏ ‏وَبَقِيَ ‏ ‏خُبَيْبُ بْنُ عَدِيٍّ ‏ ‏وَزَيْدُ بْنُ الدَّثِنَةِ ‏ ‏وَرَجُلٌ آخَرُ فَأَعْطَوْهُمْ الْعَهْدَ وَالْمِيثَاقَ إِنْ نَزَلُوا إِلَيْهِمْ فَلَمَّا اسْتَمْكَنُوا مِنْهُمْ حَلُّوا أَوْتَارَ ‏ ‏قِسِيِّهِمْ ‏ ‏فَرَبَطُوهُمْ بِهَا فَقَالَ الرَّجُلُ الثَّالِثُ الَّذِي مَعَهُمَا هَذَا أَوَّلُ الْغَدْرِ فَأَبَى أَنْ يَصْحَبَهُمْ فَجَرُّوهُ فَأَبَى أَنْ يَتْبَعَهُمْ فَضَرَبُوا عُنُقَهُ فَانْطَلَقُوا ‏ ‏بِخُبَيْبِ بْنِ عَدِيٍّ ‏ ‏وَزَيْدِ بْنِ الدَّثِنَةِ ‏ ‏حَتَّى بَاعُوهُمَا ‏ ‏بِمَكَّةَ ‏ ‏فَاشْتَرَى ‏ ‏خُبَيْبًا ‏ ‏بَنُو الْحَارِثِ بْنِ عَامِرِ بْنِ نَوْفَلٍ ‏ ‏وَكَانَ قَدْ قَتَلَ ‏ ‏الْحَارِثَ ‏ ‏يَوْمُ ‏ ‏بَدْرٍ ‏ ‏فَمَكَثَ عِنْدَهُمْ أَسِيرًا حَتَّى إِذَا أَجْمَعُوا قَتْلَهُ اسْتَعَارَ مُوسَى مِنْ إِحْدَى بَنَاتِ ‏ ‏الْحَارِثِ ‏ ‏لِيَسْتَحِدَّ ‏ ‏بِهَا ‏ ‏فَأَعَارَتْهُ ‏ ‏قَالَتْ فَغَفَلْتُ عَنْ صَبِيٍّ لِي ‏ ‏فَدَرَجَ ‏ ‏إِلَيْهِ حَتَّى أَتَاهُ قَالَتْ فَأَخَذَهُ فَوَضَعَهُ عَلَى فَخِذِهِ فَلَمَّا رَأَيْتُهُ فَزِعْتُ فَزَعًا عَرَفَهُ وَالْمُوسَى فِي يَدِهِ فَقَالَ أَتَخْشَيْنَ أَنْ أَقْتُلَهُ مَا كُنْتُ لِأَفْعَلَ إِنْ شَاءَ اللَّهُ قَالَ وَكَانَتْ تَقُولُ مَا رَأَيْتُ أَسِيرًا خَيْرًا مِنْ ‏ ‏خُبَيْبٍ ‏ ‏قَدْ رَأَيْتُهُ يَأْكُلُ مِنْ قِطْفِ عِنَبٍ وَمَا ‏ ‏بِمَكَّةَ ‏ ‏يَوْمَئِذٍ ثَمَرَةٌ وَإِنَّهُ لَمُوثَقٌ فِي الْحَدِيدِ وَمَا كَانَ إِلَّا رِزْقًا رَزَقَهُ اللَّهُ إِيَّاهُ قَالَ ثُمَّ خَرَجُوا بِهِ مِنْ ‏ ‏الْحَرَمِ ‏ ‏لِيَقْتُلُوهُ فَقَالَ ‏ ‏دَعُونِي أُصَلِّي رَكْعَتَيْنِ فَصَلَّى رَكْعَتَيْنِ فَقَالَ لَوْلَا أَنْ تَرَوْا مَا بِي جَزَعًا مِنْ الْمَوْتِ لَزِدْتُ قَالَ وَكَانَ أَوَّلَ مَنْ سَنَّ الرَّكْعَتَيْنِ عِنْدَ الْقَتْلِ هُوَ ثُمَّ قَالَ اللَّهُمَّ أَحْصِهِمْ عَدَدًا ‏ ‏مَا أُبَالِي حِينَ أُقْتَلُ مُسْلِمًا ‏ ‏عَلَى أَيِّ ‏ ‏شِقٍّ ‏ ‏كَانَ لِلَّهِ مَصْرَعِي ‏ ‏وَذَلِكَ فِي ذَاتِ الْإِلَهِ وَإِنْ يَشَأْ ‏ ‏يُبَارِكْ عَلَى أَوْصَالِ ‏ ‏شِلْوٍ ‏ ‏مُمَزَّعِ ‏ ‏ثُمَّ قَامَ إِلَيْهِ ‏ ‏عُقْبَةُ بْنُ الْحَارِثِ ‏ ‏فَقَتَلَهُ وَبَعَثَتْ ‏ ‏قُرَيْشٌ ‏ ‏إِلَى ‏ ‏عَاصِمٍ ‏ ‏لِيُؤْتَوْا بِشَيْءٍ مِنْ جَسَدِهِ يَعْرِفُونَهُ وَكَانَ قَتَلَ عَظِيمًا مِنْ عُظَمَائِهِمْ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَبَعَثَ اللَّهُ عَلَيْهِ مِثْلَ الظُّلَّةِ مِنْ ‏ ‏الدَّبْرِ ‏ ‏فَحَمَتْهُ مِنْ رُسُلِهِمْ فَلَمْ يَقْدِرُوا عَلَى شَيْءٍ مِنْهُ ‏","","",""],[7750,7750,"","আমার বাবার কথা বলেছিলাম আমার ভাই একজন উৎপীড়ক, ঈশ্বর মুক্তি দিয়েছেন আর তার প্রত্যেক কুকুর বা ঘণ্টাে তুমি আশীর্বাদ পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا كَلْبٌ أَوْ جَرَسٌ ‏","","",""],[7751,7751,"","ঈশ্বর আমাদের সন্তানদের আমি যে - ত্রিভুজগুলো দিয়েছেন, সেগুলো পান করার জন্য আমাকে নিযুক্ত করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَدُ الزِّنَا أَشَرُّ الثَّلَاثَةِ ‏","","",""],[7752,7752,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার আশীর্বাদ থেকে তার আত্মা উদ্ধার করবেন একা.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ يَعْنِي ابْنَ عُتْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ السُّحَيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ بِالْخِيَارِ مِنْ بَيْعِهِمَا مَا لَمْ يَتَفَرَّقَا أَوْ يَكُونُ بَيْعُهُمَا فِي خِيَارٍ ‏","","",""],[7753,7753,"","আমার বাবার ব্যাপারে আমরা কথা বলেছি যে ঈশ্বর তার কাছে প্রার্থনা করেছেন। লোকটি তার ভাইয়ের পরিকল্পনা পছন্দ করবে না, তার ভুল নয়।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبْتَاعُ الرَّجُلُ عَلَى بَيْعِ أَخِيهِ وَلَا يَخْطُبُ عَلَى خِطْبَتِهِ وَلَا تَشْتَرِطُ الْمَرْأَةُ طَلَاقَ أُخْتِهَا ‏ ‏لِتَسْتَفْرِغَ ‏ ‏صَحْفَتَهَا فَإِنَّمَا لَهَا مَا كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَهَا ‏","","",""],[7754,7754,"","বাবার মৃত্যুর কথা বলেছিলাম, আমি তাকে আর কখনো বাঁচতে দেবো না।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْفَرَجُ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعْدٍ الْحِمْصِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَعَوَاتٌ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَتْرُكُهَا مَا عِشْتُ حَيًّا سَمِعْتُهُ يَقُولُ ‏ ‏اللَّهُمَّ اجْعَلْنِي أُعْظِمُ شُكْرَكَ وَأُكْثِرُ ذِكْرَكَ وَأَتْبَعُ نَصِيحَتَكَ وَأَحْفَظُ وَصِيَّتَكَ ‏","","",""],[7755,7755,"","আমার বাবা একজন মাতাল মানুষ হওয়া সম্পর্কে আমরা কথা বলেছি । তার ফোন শেষ তিন ঘণ্টা.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قِيلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَيِّ شَيْءٍ سُمِّيَ يَوْمُ الْجُمُعَةِ قَالَ ‏ ‏لِأَنَّ فِيهَا طُبِعَتْ طِينَةُ أَبِيكَ ‏ ‏آدَمَ ‏ ‏وَفِيهَا ‏ ‏الصَّعْقَةُ ‏ ‏وَالْبَعْثَةُ وَفِيهَا الْبَطْشَةُ وَفِي آخِرِ ثَلَاثِ سَاعَاتٍ مِنْهَا سَاعَةٌ مَنْ دَعَا اللَّهَ عَزَّ وَجَلَّ فِيهَا اسْتُجِيبَ لَهُ ‏","","",""],[7756,7756,"","আমি যে ল্যাডারটা নিতে ব্যর্থ হয়েছি, তা না নেওয়া এবং সেটাকে ঘৃণা না করা পর্যন্ত আমি সেই মইকে পৌঁছে দিতে ব্যর্থ হয়েছি ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ وَلَا يَحْقِرُهُ وَحَسْبُ امْرِئٍ مِنْ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ ‏","","",""],[7757,7757,"","আমি কথা বলেছি এবং এমনকি খেয়ালও করিনি। আমার বাবা আমার বাবার উপর অত্যাচার করেছে। যখন পানি খুলে গেল, তখন সে ডুবে গেল আর তারপর সে ডুবে গেল। আমি বললাম দুই হিস্টোরি, যদি আমি এখানে যাই, আমি পানি নিয়ে যাব অথবা তার বালিশ দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏الْمَعْنَى وَاللَّفْظُ لَفْظُ ‏ ‏يَحْيَى بْنِ آدَمَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَلَاءَ ‏ ‏فَأَتَيْتُهُ ‏ ‏بِتَوْرٍ ‏ ‏فِيهِ مَاءٌ ‏ ‏فَاسْتَنْجَى ‏ ‏ثُمَّ مَسَحَ يَدَهُ فِي الْأَرْضِ ثُمَّ غَسَلَهَا ثُمَّ أَتَيْتُهُ ‏ ‏بِتَوْرٍ ‏ ‏آخَرَ فَتَوَضَّأَ بِهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏أَسْوَدُ يَعْنِي شَاذَانَ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏أَتَيْتُهُ بِمَاءٍ فِي ‏ ‏تَوْرٍ ‏ ‏أَوْ فِي ‏ ‏رَكْوَةٍ ‏ ‏وَذَكَرَهُ بِإِسْنَادِهِ ‏","","",""],[7758,7758,"","আমি আমার বাবার একজন বেশ্যা হওয়ার বিষয়ে কথা বলেছিলাম । সব ধরণের দায় থেকে বের হয়ে যাও, প্রতি মাসে তিন দিন পর আর আমি কথা বলছি যে তৃতীয়বার... ...আর একটা বই দিয়ে একটা বই বানানো হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَلَاثٍ وَنَهَانِي عَنْ ثَلَاثٍ ‏ ‏أَمَرَنِي بِرَكْعَتَيْ الضُّحَى كُلَّ يَوْمٍ ‏ ‏وَالْوِتْرِ ‏ ‏قَبْلَ النَّوْمِ وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَنَهَانِي عَنْ نَقْرَةٍ كَنَقْرَةِ الدِّيكِ ‏ ‏وَإِقْعَاءٍ ‏ ‏كَإِقْعَاءِ ‏ ‏الْكَلْبِ وَالْتِفَاتٍ كَالْتِفَاتِ الثَّعْلَبِ ‏","","",""],[7759,7759,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমার বাবার কাছ থেকে পালিয়ে গিয়েছিল, যে তাকে ছেড়ে দিতে পারবে না। আর সে তার অমরত্বের প্রভাব দেখতে পছন্দ করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏ابْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ أَنْ يَرَى أَثَرَ نِعْمَتِهِ عَلَى عَبْدِهِ ‏","","",""],[7760,7760,"","আমি বাবার সম্পর্কে কথা বলেছিলাম, আমার বাবাকে নগ্ন হতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَجْلِسَ أَحَدُكُمْ عَلَى جَمْرَةٍ فَتُحْرِقَ ثِيَابَهُ حَتَّى ‏ ‏تُفْضِيَ ‏ ‏إِلَى جِلْدِهِ خَيْرٌ لَهُ ‏ ‏مِنْ أَنْ يَجْلِسَ عَلَى قَبْرٍ ‏","","",""],[7761,7761,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমার বাবা, আমার ছেলে আমার ঈশ্বর । অবশ্যই.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سَلْمِ بْنِ عَبْدِ الرَّحْمَنِ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَسَمَّى بِاسْمِي فَلَا ‏ ‏يَتَكَنَّى بِكُنْيَتِي وَمَنْ اكْتَنَى بِكُنْيَتِي فَلَا ‏ ‏يَتَسَمَّى بِاسْمِي ‏","","",""],[7762,7762,"","ঈশ্বর তাঁর এই কথা বলে নিজেকে সমর্পণ করেছেন যে, প্রভুর বাক্য দ্বারা তারা এই কথা বলে তাদেরকে ডাকা হয়েছে । বারে লাইন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏ادْخُلُوا الْبَابَ سُجَّدًا ‏} ‏قَالَ دَخَلُوا زَحْفًا ‏ { ‏وَقُولُوا ‏ ‏حِطَّةٌ ‏ } ‏قَالَ بَدَّلُوا فَقَالُوا ‏ ‏حِنْطَةٌ ‏ ‏فِي شَعَرَةٍ ‏","","",""],[7763,7763,"","ঈশ্বর বলে দেবেন যে, উত্তম কথা সত্য এবং সমস্ত পরিকল্পনা প্রার্থনায় বা কথা বলাকে লজ্জাদায়ক করে তুলবে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ وَكُلُّ خُطْوَةٍ يَمْشِيهَا إِلَى الصَّلَاةِ ‏ ‏أَوْ قَالَ إِلَى الْمَسْجِدِ ‏ ‏صَدَقَةٌ ‏","","",""],[7764,7764,"","ঈশ্বর তাকে যুদ্ধের গাল নামে একটা মই দিয়ে সমর্পণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سَمَّى الْحَرْبَ خَدْعَةً ‏","","",""],[7765,7765,"","আমরা এমন একটা ছেলের সঙ্গে কথা বলেছিলাম, যিনি মুক্ত ছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْخَضِرِ ‏ ‏قَالَ ‏ ‏إِنَّمَا سُمِّيَ ‏ ‏خَضِرًا ‏ ‏أَنَّهُ جَلَسَ عَلَى فَرْوَةٍ بَيْضَاءَ فَإِذَا هِيَ تَحْتَهُ تَهْتَزُّ خَضْرَاءَ ‏","","",""],[7766,7766,"","আমরা বাবার ছেলের সাথে প্রেম করেছি, আমি আনন্দের সাথে একটা কুঁড়েঘরের ছেলে শুনতে চাই, ঈশ্বর বলেছিলেন তিনি উদ্ধার করতে হবে এবং জীবিত মানুষের কাছে বিক্রি করতে হবে তাহলে তুমি আগুন চাইবে আর ভালবাসা আসবে আর চলে যাবে, তারা বাইরে যাবে আর আমরা এটা জিততে পারব।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ سَمْعَانَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَايَعُ لِرَجُلٍ بَيْنَ الرُّكْنِ ‏ ‏وَالْمَقَامِ ‏ ‏وَلَنْ يَسْتَحِلَّ ‏ ‏الْبَيْتَ ‏ ‏إِلَّا أَهْلُهُ فَإِذَا اسْتَحَلُّوهُ فَلَا تَسْأَلْ عَنْ هَلَكَةِ ‏ ‏الْعَرَبِ ‏ ‏ثُمَّ تَجِيءُ ‏ ‏الْحَبَشَةُ ‏ ‏فَيُخَرِّبُونَهُ خَرَابًا لَا يَعْمُرُ بَعْدَهُ أَبَدًا هُمْ الَّذِينَ يَسْتَخْرِجُونَ كَنْزَهُ ‏","","",""],[7767,7767,"","আমরা কথা বলেছিলাম, তিনি কি করে বলেছিলেন, ঈশ্বর একবার তার জন্য প্রার্থনা করেছেন এবং তিনি বাকী মানুষদের উদ্ধার করেছেন, তারা মারা গেছে, তারা সবাই ঈশ্বরের ক্ষতি করেছে। শুটার আগামীকাল হয়.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ بْنُ هَمَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ ‏ ‏هَذَا مَا حَدَّثَنَا بِهِ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ بَيْدَ أَنَّهُمْ أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا وَأُوتِينَاهُ مِنْ بَعْدِهِمْ فَهَذَا يَوْمُهُمْ الَّذِي فَرَضَ اللَّهُ عَلَيْهِمْ فَاخْتَلَفُوا فِيهِ فَهَدَانَا اللَّهُ لَهُ فَهُمْ لَنَا فِيهِ تَبَعٌ ‏ ‏الْيَهُودُ ‏ ‏غَدًا ‏ ‏وَالنَّصَارَى ‏ ‏بَعْدَ غَدٍ ‏","","",""],[7768,7768,"","সে বলল, যাজক তার জন্য প্রার্থনা করে এবং সে আমার আদর্শকে আত্মসমর্পণ করবে এবং পিতা হিসেবে আমি তাকে একটা বিল্ডিং বানাতে চাই না যাতে মানুষ রান্না করে কিন্তু তুমি তোমার ছেলের স্বরণ নির্মাণ করছো... ...যে ঈশ্বর কখনো এই উপহার দিয়েছেন.","‏ ‏وَقَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ ابْتَنَى بُيُوتًا فَأَحْسَنَهَا وَأَكْمَلَهَا وَأَجْمَلَهَا إِلَّا مَوْضِعَ ‏ ‏لَبِنَةٍ ‏ ‏مِنْ زَاوِيَةٍ مِنْ زَوَايَاهَا فَجَعَلَ النَّاسُ يَطُوفُونَ وَيُعْجِبُهُمْ الْبُنْيَانُ فَيَقُولُونَ أَلَا وَضَعْتَ هَاهُنَا ‏ ‏لَبِنَةً ‏ ‏فَيَتِمُّ بُنْيَانُكَ فَقَالَ ‏ ‏مُحَمَّدٌ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنْتُ أَنَا ‏ ‏اللَّبِنَةَ ‏","","",""],[7769,7769,"","আগুন জ্বালানোর স্থানগুলো তাদের ওপর দিয়ে আমাকে অবাক করে দেয় এবং আমি অবাক হই যে, আগুনকে আগুন বলে দায়ী করা হয়েছে ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلِي كَمَثَلِ رَجُلٍ اسْتَوْقَدَ نَارًا فَلَمَّا أَضَاءَتْ مَا حَوْلَهَا جَعَلَ الْفَرَاشُ وَهَذِهِ الدَّوَابُّ الَّتِي يَقَعْنَ فِي النَّارِ يَقَعْنَ فِيهَا وَجَعَلَ يَحْجِزُهُنَّ وَيَغْلِبْنَهُ فَتَتَقَحَّمُ فِيهَا قَالَ فَذَلِكُمْ مَثَلِي وَمَثَلُكُمْ أَنَا آخِذٌ بِحُجَزِكُمْ عَنْ النَّارِ هَلُمَّ عَنْ النَّارِ هَلُمَّ عَنْ النَّارِ هَلُمَّ فَتَغْلِبُونِي تَقْتَحِمُونَ فِيهَا ‏","","",""],[7770,7770,"","তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি আপনার কাছে আত্মসমর্পণ করবেন এবং মনে করেছিলেন যে শুধুমাত্র পদক্ষেপটি হবে। এবং ঈশ্বরের দাস হবেন না, ভাই।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ وَلَا تَحَاسَدُوا وَلَا تَنَافَسُوا وَلَا تَبَاغَضُوا وَلَا تَدَابَرُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[7771,7771,"","তিনি বললেন, আল্লাহ তাঁর কাছে প্রার্থনা করুন এবং সমাজের কাছে আত্মসমর্পণ করবেন। তিনি এক ঘন্টার মধ্যে কোন চূড়ান্ত সিদ্ধান্ত, অবিশ্বাস্য এবং অসুখীতার মধ্যে দিয়ে।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجُمُعَةِ سَاعَةٌ لَا يُوَافِقُهَا مُسْلِمٌ وَهُوَ يَسْأَلُ رَبَّهُ شَيْئًا إِلَّا آتَاهُ إِيَّاهُ ‏","","",""],[7772,7772,"","তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করবেন এবং তিনি আপনার রানীকে আপনার ওক গাছের মধ্যে দেখতে পারবেন । আপনি তাদের প্রার্থনা করতে দিন এবং প্রার্থনা করতে দিন ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَلَائِكَةُ ‏ ‏يَتَعَاقَبُونَ ‏ ‏فِيكُمْ مَلَائِكَةٌ بِاللَّيْلِ وَمَلَائِكَةٌ بِالنَّهَارِ وَقَالَ يَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ ثُمَّ ‏ ‏يَعْرُجُ ‏ ‏إِلَيْهِ الَّذِينَ بَاتُوا فِيكُمْ فَيَسْأَلُهُمْ وَهُوَ أَعْلَمُ كَيْفَ تَرَكْتُمْ عِبَادِي فَقَالُوا تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ ‏","","",""],[7773,7773,"","ঈশ্বর তাদের ক্ষমা করবেন ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَلَائِكَةُ تُصَلِّي عَلَى أَحَدِكُمْ مَا دَامَ فِي مُصَلَّاهُ الَّذِي صَلَّى فِيهِ مَا لَمْ ‏ ‏يُحْدِثْ ‏ ‏اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ ‏","","",""],[7774,7774,"","সে তার পাপের হাত থেকে বেরিয়ে আসছে।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ أَحَدُكُمْ آمِينَ وَالْمَلَائِكَةُ فِي السَّمَاءِ فَيُوَافِقُ إِحْدَاهُمَا الْأُخْرَى غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[7775,7775,"","সে বলল, যখন কোন মানুষ একটা বাজে ঋণের কারণে ধরা পড়ে তখন সে বলল সে ঈশ্বরের অনুগ্রহ পেয়েছে।","‏ ‏وَقَالَ بَيْنَمَا رَجُلٌ يَسُوقُ بَدَنَةً ‏ ‏مُقَلَّدَةً ‏ ‏قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلَكَ ارْكَبْهَا قَالَ بَدَنَةٌ يَا رَسُولَ اللَّهِ قَالَ وَيْلَكَ ارْكَبْهَا ‏","","",""],[7776,7776,"","তিনি বলেছিলেন, ঈশ্বর তার কাছে প্রার্থনা করেন এবং যদি আপনি জানেন আমি কি করব, যদি আপনি জানতে পারেন, আপনার পিতা অনেক মহান ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَوْ تَعْلَمُونَ ‏ ‏مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[7777,7777,"","তিনি বললেন, ঈশ্বর তাঁর জন্য প্রার্থনা করুন এবং তিনি আপনাকে হত্যা করা হলে আত্মসমর্পণ করবেন।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَجْتَنِبْ الْوَجْهَ ‏","","",""],[7778,7778,"","ঈশ্বর যথেষ্ট লজ্জা লাভ করেছেন, প্রভু, তিনি বলেছিলেন যে, তিনি তার সমস্ত কিছু করতে ইচ্ছুক ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَارُكُمْ هَذِهِ مَا يُوقِدُ بَنُو ‏ ‏آدَمَ ‏ ‏جُزْءٌ وَاحِدٌ مِنْ سَبْعِينَ جُزْءًا مِنْ حَرِّ جَهَنَّمَ قَالُوا وَاللَّهِ إِنْ كَانَتْ لَكَافِيَةً يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهَا فُضِّلَتْ عَلَيْهَا بِتِسْعٍ وَسِتِّينَ جُزْءًا كُلُّهُنَّ مِثْلُ حَرِّهَا ‏","","",""],[7779,7779,"","তিনি বলেন, আল্লাহ প্রার্থনা করেন তিনি ঈশ্বরের দোহাইর কাছে আত্মসমর্পণ করবেন, তিনি অন্ধকারে তার বই লিখেছেন।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ كِتَابًا فَهُوَ عِنْدَهُ فَوْقَ الْعَرْشِ إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي ‏","","",""],[7780,7780,"","সে বলল, ঈশ্বর তার কাছে প্রার্থনা করবে আর প্রভু যদি তোমাকে বিশ্বাস করি, সে তাকে মেরে ফেলবে, অথবা সে তাকে গন্ধও দেবে।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصِّيَامُ جُنَّةٌ فَإِذَا كَانَ أَحَدُكُمْ يَوْمًا صَائِمًا فَلَا يَجْهَلْ وَلَا ‏ ‏يَرْفُثْ ‏ ‏فَإِنْ امْرُؤٌ قَاتَلَهُ أَوْ شَتَمَهُ فَلْيَقُلْ إِنِّي صَائِمٌ إِنِّي صَائِمٌ ‏","","",""],[7781,7781,"","মাছগুলো তার আবেগ এবং তার রীতিনীতি দেখতে পাবে এবং আমার সাহস ও সন্দেহের মধ্যে তার সন্দেহগুলো দেখতে পাবে । আমি এটায় আছি।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏ ‏يَذَرُ ‏ ‏شَهْوَتَهُ وَطَعَامَهُ وَشَرَابَهُ مِنْ جَرَّايَ فَالصِّيَامُ لِي وَأَنَا أَجْزِي بِهِ ‏","","",""],[7782,7782,"","ঈশ্বরের দয়া তাকে আদেশ দিয়েছে আর যুদ্ধের আগুনটা দেবে, যে যাকে আগুন দিয়ে আগুন দেয়া হয়েছিল তাকে যেন আগুনের মধ্যে পোড়ানো হয়, যদি আমরা শুধু এক দুলি হই।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ نَبِيٌّ مِنْ الْأَنْبِيَاءِ تَحْتَ شَجَرَةٍ فَلَدَغَتْهُ نَمْلَةٌ فَأَمَرَ ‏ ‏بِجَهَازِهِ ‏ ‏فَأُخْرِجَ مِنْ تَحْتِهَا وَأَمَرَ بِالنَّارِ فَأُحْرِقَتْ فِي النَّارِ قَالَ فَأَوْحَى اللَّهُ إِلَيْهِ فَهَلَّا نَمْلَةً وَاحِدَةً ‏","","",""],[7783,7783,"","তিনি বলেছিলেন, ঈশ্বর প্রার্থনা করেছেন, যদি আমি বেঁচে না থাকি, তাহলে তিনি আমার প্রভুর দাসকে তার হাতে রাখবেন। আমি আনন্দিত যে তুমি ঈশ্বরের পথে আছো, কিন্তু আমি তাদের ধরতে এক ঘন্টা সময় পাচ্ছি না এবং তারা আমাকে ধরতেও না। কোন উপায় নেই।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏فِي يَدِهِ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى الْمُؤْمِنِينَ مَا قَعَدْتُ خَلْفَ سَرِيَّةٍ ‏ ‏تَغْزُو فِي سَبِيلِ اللَّهِ وَلَكِنْ لَا أَجِدُ سَعَةً فَأَحْمِلَهُمْ وَلَا يَجِدُونَ سَعَةً فَيَتَّبِعُونِي وَلَا تَطِيبُ أَنْفُسُهُمْ أَنْ يَقْعُدُوا بَعْدِي ‏","","",""],[7784,7784,"","ঈশ্বরের দোহাই, সে বলেছে যে তার কাছে যা আছে তার সব অগ্নি-ছন্নতা তাকে দিতে হবে।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ تُسْتَجَابُ لَهُ وَأُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أُؤَخِّرَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[7785,7785,"","ঈশ্বরের দয়ায় তিনি আদেশ দিয়েছেন এবং আমি ঈশ্বরের প্রতি প্রেম করি, তাঁর সাথে দেখা করতে।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ لَمْ يُحِبَّ لِقَاءَ اللَّهِ لَمْ يُحِبَّ اللَّهُ لِقَاءَهُ ‏","","",""],[7786,7786,"","তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমাকে বাধ্য হতে অনুপ্রাণিত করবেন। তিনি আমাকে রাজকুমারের কষ্ট দিয়েছেন। তিনি আমার ছড়ি হারিয়ে ফেলেন।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ ‏ ‏يَعْصِينِي فَقَدْ عَصَى اللَّهَ وَمَنْ يُطِعْ الْأَمِيرَ فَقَدْ أَطَاعَنِي وَمَنْ يَعْصِ الْأَمِيرَ فَقَدْ عَصَانِي ‏","","",""],[7787,7787,"","তিনি বলেছিলেন যে, ঈশ্বর এমনকি পয়সার ওপর দিয়ে যেতে এবং এমনকি টাকা বাঁচানোর জন্য ঘন্টার পর ঘন্টাও দেবেন না ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَكْثُرَ فِيكُمْ الْمَالُ وَيَفِيضَ حَتَّى يُهِمَّ رَبَّ الْمَالِ مَنْ يَقْبَلُ مِنْهُ صَدَقَتَهُ ‏","","",""],[7788,7788,"","সে বলেছে সে শপথ নিতে পারে এবং মারা যেতে পারে এবং তাকে পলাতক হিসেবে দেখা হবে।","‏ ‏وَقَالَ ‏ ‏وَيُقْبَضَ الْعِلْمُ وَيَقْتَرِبَ الزَّمَانُ وَتَظْهَرَ الْفِتَنُ وَيَكْثُرَ الْهَرْجُ قَالُوا الْهَرْجُ أَيُّمَا هُوَ يَا رَسُولَ اللَّهِ قَالَ الْقَتْلُ الْقَتْلُ ‏","","",""],[7789,7789,"","ঈশ্বরের দয়া তাকে আদেশ দিয়েছে আর মরার আগ পর্যন্ত সেবা করবে না, তারা তাদের একটাকে বলে।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَقْتَتِلَ فِئَتَانِ عَظِيمَتَانِ يَكُونُ بَيْنَهُمَا مَقْتَلَةٌ عَظِيمَةٌ وَدَعْوَاهُمَا وَاحِدَةٌ ‏","","",""],[7790,7790,"","তিনি বললেন ভগবানের কাছে প্রার্থনা করা হয়েছে যেন তিনি কিছু শব্দ দ্বারা উত্তরাধিকারী হিসেবে সেবা না করেন। আমি ঈশ্বরের সাথে ঝামেলা করছি।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَنْبَعِثَ دَجَّالُونَ كَذَّابُونَ قَرِيبًا مِنْ ثَلَاثِينَ كُلُّهُمْ يَزْعُمُ أَنَّهُ رَسُولُ اللَّهِ ‏","","",""],[7791,7791,"","তিনি বলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি তাঁর মুখ থেকে সূর্য তুলে না নেওয়া পর্যন্ত তিনি তা উদ্ধার করা হবে না। আমি আপনার মনের সাথে সাক্ষাৎ করছি যখন এটা বিশ্বাস করা কঠিন ছিল এটা নিরাপদ নয়। আমি ছিলাম.","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا فَإِذَا طَلَعَتْ وَرَآهَا النَّاسُ آمَنُوا أَجْمَعُونَ وَذَلِكَ حِينَ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏}","","",""],[7792,7792,"","তিনি বলেন, ঈশ্বর প্রার্থনা করেছিলেন যদি তিনি আমাকে প্রার্থনা করতে চাইতেন যে তিনি ক্ষতিগ্রস্ত হবেন। আমি যদি করি, আমি ঠিক থাকবো। আমি কি মনে রাখবেন যখন তিনি আগে কিছু মনে করতে পারেন না? সে এমনকি তাকে দৌড়াতেও বাধা দিয়েছিল।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نُودِيَ بِالصَّلَاةِ ‏ ‏أَدْبَرَ ‏ ‏الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ فَإِذَا قُضِيَ التَّأْذِينُ أَقْبَلَ حَتَّى إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِهَا ‏ ‏أَدْبَرَ ‏ ‏حَتَّى إِذَا قُضِيَ ‏ ‏التَّثْوِيبُ ‏ ‏أَقْبَلَ حَتَّى يَخْطِرَ بَيْنَ الْمَرْءِ وَنَفْسِهِ فَيَقُولَ لَهُ اذْكُرْ كَذَا اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يُذْكَرُ مِنْ قَبْلُ حَتَّى يَظَلَّ الرَّجُلُ إِنْ يَدْرِي كَيْفَ صَلَّى ‏","","",""],[7793,7793,"","তিনি বলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং ঈশ্বর তাকে ঈশ্বরের আনন্দ থেকে মুক্ত না করতে তাঁর উপর প্রার্থনা করুন।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ يَمِينَ اللَّهِ مَلْأَى لَا ‏ ‏يَغِيضُهَا ‏ ‏نَفَقَةٌ ‏ ‏سَحَّاءُ ‏ ‏اللَّيْلَ وَالنَّهَارَ أَرَأَيْتُمْ مَا أَنْفَقَ مُنْذُ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ فَإِنَّهُ لَمْ ‏ ‏يَغِضْ ‏ ‏مَا فِي يَمِينِهِ قَالَ وَعَرْشُهُ عَلَى الْمَاءِ وَبِيَدِهِ الْأُخْرَى الْقَبْضُ يَرْفَعُ وَيَخْفِضُ ‏","","",""],[7794,7794,"","তিনি বলেছিলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি আপনার কাছে আপনার কাছে আপনার প্রভুর কাছে প্রার্থনা করবেন ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَيَأْتِيَنَّ عَلَى أَحَدِكُمْ يَوْمٌ لَأَنْ يَرَانِي ثُمَّ لَأَنْ يَرَانِي أَحَبُّ إِلَيْهِ مِنْ أَهْلِهِ وَمَالِهِ وَمِثْلِهِمْ مَعَهُمْ ‏","","",""],[7795,7795,"","তিনি ঈশ্বর প্রার্থনা তিনি আপনাকে আত্মসমর্পণ করা হবে এবং তারপর তিনি তার পর কখনো চলে যায়নি. তিনি তার পেট হারিয়েছে এবং তাদের ওজন ঈশ্বরের খুশির পথে ভাগ করে এবং তিনি হয় হয়. খুন।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلَكَ ‏ ‏كِسْرَى ‏ ‏ثُمَّ لَا يَكُونُ ‏ ‏كِسْرَى ‏ ‏بَعْدَهُ ‏ ‏وَقَيْصَرُ ‏ ‏لَيَهْلِكَنَّ ثُمَّ لَا يَكُونُ ‏ ‏قَيْصَرُ ‏ ‏بَعْدَهُ وَلَتُقَسِّمُنَّ كُنُوزَهُمَا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[7796,7796,"","সে বলল ভগবান তার কাছে প্রার্থনা করুক আর সে আত্মসমর্পণ করবে যে খোদা আমার কাছে ফিরে আসবে না।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ ‏أَعْدَدْتُ لِعِبَادِي الصَّالِحِينَ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏","","",""],[7797,7797,"","তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি আমাকে আপনার বাবা-মা'র কাছে যা দিতে চান আমাকে দিবেন। আমি তাদের বিল্ডিং তৈরি করছি, যাতে আপনার প্রয়োজন অথবা ক্রম অনুযায়ী কাজ শেষ করতে পারি।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَرُونِي مَا تَرَكْتُكُمْ فَإِنَّمَا أُهْلِكَ الَّذِينَ مِنْ قَبْلِكُمْ بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ فَإِذَا نَهَيْتُكُمْ عَنْ شَيْءٍ فَاجْتَنِبُوهُ وَإِذَا ‏ ‏أَمَرْتُكُمْ بِأَمْرٍ فَأْتَمِرُوا مَا اسْتَطَعْتُمْ ‏","","",""],[7798,7798,"","তিনি বলেছিলেন, ঈশ্বর তার কাছে প্রার্থনা করেন এবং তিনি আত্মসমর্পণ করবেন যদি আমি প্রাত্যহিক সকালে তোমার কাছে পৌঁছাতে চাই এবং তোমাদের একত্রিত করতে চাই।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ صَلَاةِ الصُّبْحِ وَأَحَدُكُمْ جُنُبٌ فَلَا يَصُمْ يَوْمَئِذٍ ‏","","",""],[7799,7799,"","সে বলল ভগবানের কাছে সাহায্য চেয়েছে, তাকে সাহায্য করতে।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ تِسْعَةٌ وَتِسْعُونَ اسْمًا مِائَةٌ إِلَّا وَاحِدًا مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ إِنَّهُ ‏ ‏وِتْرٌ ‏ ‏يُحِبُّ ‏ ‏الْوِتْرَ ‏","","",""],[7800,7800,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তিনি তাঁর জন্য প্রার্থনা করতেন এবং তিনি আপনাকে যদি দেখতে চাই তিনি তাকে স্বপ্নে পছন্দ করতেন এবং বলেন তিনি তার জীবনের সেরা হবে, আমি তার কাছে ক্ষমা প্রার্থনা করছি। তার চেয়ে ভালো।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَظَرَ أَحَدُكُمْ إِلَى مَنْ فُضِّلَ عَلَيْهِ فِي الْمَالِ وَالْخُلُقِ فَلْيَنْظُرْ إِلَى مَنْ هُوَ أَسْفَلَ مِنْهُ فِيمَنْ فُضِّلَ عَلَيْهِ ‏","","",""]];
